// ═══════════════════════════════════════════════════════════════════════════
// MY DASHBOARD — self-contained. To revert: remove this block + 3 lines below.
// ═══════════════════════════════════════════════════════════════════════════
function MyDashboard({csms=[], filterCoach="", filterCSM="", callData={},
  churnAlerts=[], qamc=[], qass=[], domoBoq=[], q3BobCur=[], q3Supp=[], rawRev=[], cadenceFull=[], onNavigate=()=>{}, onSetTrendsTab=()=>{}, onSetBobTab=()=>{}, cerAssigned=[], cerCompleted=[], fiRows=[], sfBobRows=[]}) {
  const [dashDateFilter, setDashDateFilter] = React.useState("today");
  const [dashCustomFrom, setDashCustomFrom] = React.useState("");
  const [dashCustomTo,   setDashCustomTo]   = React.useState("");
  const [alertFilter, setAlertFilter]       = React.useState("all");

  const pad  = n => String(n).padStart(2,"0");
  const pp   = p => p!=null?(p*100).toFixed(1)+"%":"--";
  const cc   = r => r==null?"#808080":r>=0.85?"#16a34a":r>=0.70?"#d97706":"#dc2626";
  const nsc  = r => r==null?"#808080":r<=0.05?"#16a34a":r<=0.10?"#d97706":"#dc2626";
  const fd   = n => "$"+Number(n||0).toLocaleString("en-US",{minimumFractionDigits:0,maximumFractionDigits:0});
  const fk   = n => n>=1000?"$"+(n/1000).toFixed(1).replace(/\.0$/,"")+"k":"$"+Math.round(n);
  const pf   = v => { const x=parseFloat(String(v||0).replace(/[$,]/g,"")); return isNaN(x)?0:x; };
  const gC   = (r,...ks) => { for(const k of ks){ if(r[k]!=null) return r[k]; } return null; };
  const lfSwap = n => { if(!n)return n; const p=n.split(","); return p.length===2?p[1].trim()+" "+p[0].trim():n; };

  const now          = new Date();

  // ── Calendar date boundaries (same logic as Calls tab) ────────────────────
  const getMon2  = d => { const dt=new Date(d); dt.setHours(0,0,0,0); const dy=dt.getDay(); dt.setDate(dt.getDate()-(dy===0?6:dy-1)); return dt; };
  const thisWkMon = getMon2(now);
  const thisWkSun = new Date(thisWkMon); thisWkSun.setDate(thisWkMon.getDate()+6); thisWkSun.setHours(23,59,59,999);
  const lastWkMon = new Date(thisWkMon); lastWkMon.setDate(thisWkMon.getDate()-7);
  const lastWkSun = new Date(thisWkMon); lastWkSun.setDate(thisWkMon.getDate()-1); lastWkSun.setHours(23,59,59,999);
  const lastMoStart = new Date(now.getFullYear(), now.getMonth()-1, 1);
  const lastMoEnd   = new Date(now.getFullYear(), now.getMonth(), 0, 23, 59, 59, 999);
  const curQ2   = Math.floor(now.getMonth()/3);
  const lastQSM = curQ2===0?9:(curQ2-1)*3;
  const lastQSY = curQ2===0?now.getFullYear()-1:now.getFullYear();
  const lastQStart = new Date(lastQSY, lastQSM, 1);
  const lastQEnd   = new Date(lastQSY, lastQSM+3, 0, 23, 59, 59, 999);
  const toD = s => { if(!s)return new Date(NaN); const p=String(s).split("-"); return p.length===3?new Date(+p[0],+p[1]-1,+p[2]):new Date(NaN); };

  const nextWkMon = new Date(thisWkMon); nextWkMon.setDate(thisWkMon.getDate()+7);
  const nextWkSun = new Date(nextWkMon); nextWkSun.setDate(nextWkMon.getDate()+6); nextWkSun.setHours(23,59,59,999);

  const dashDayTest = d => {
    const wd = toD(d);
    const tS = new Date(now.getFullYear(),now.getMonth(),now.getDate(),0,0,0);
    const tE = new Date(now.getFullYear(),now.getMonth(),now.getDate(),23,59,59);
    if (dashDateFilter==="today")     return wd>=tS && wd<=tE;
    if (dashDateFilter==="this_week") return wd>=thisWkMon && wd<=thisWkSun;
    if (dashDateFilter==="next_week") return wd>=nextWkMon && wd<=nextWkSun;
    if (dashDateFilter==="last_week") return wd>=lastWkMon  && wd<=lastWkSun;
    return wd>=tS && wd<=tE; // default today
  };

  const dashLabel =
    dashDateFilter==="today"     ? `Today — ${now.toLocaleDateString("en-US",{weekday:"long",month:"short",day:"numeric"})}` :
    dashDateFilter==="this_week" ? `This week (${thisWkMon.toLocaleDateString("en-US",{month:"short",day:"numeric"})} – ${thisWkSun.toLocaleDateString("en-US",{month:"short",day:"numeric"})})` :
    dashDateFilter==="next_week" ? `Next week (${nextWkMon.toLocaleDateString("en-US",{month:"short",day:"numeric"})} – ${nextWkSun.toLocaleDateString("en-US",{month:"short",day:"numeric"})})` :
    dashDateFilter==="last_week" ? `Last week (${lastWkMon.toLocaleDateString("en-US",{month:"short",day:"numeric"})} – ${lastWkSun.toLocaleDateString("en-US",{month:"short",day:"numeric"})})` :
    `Today — ${now.toLocaleDateString("en-US",{weekday:"long",month:"short",day:"numeric"})}`;

  const coachName    = filterCoach?(COACHES.find(c=>c.e===filterCoach)||{}).n||"Team":"";
  const contextLabel = filterCSM?dispName(filterCSM):filterCoach?coachName+"'s Team":"All Teams";
  const contextIcon  = filterCSM?"👤":filterCoach?"👥":"🏢";
  const csmNames     = csms.map(c=>c.name);
  const todayStr     = now.getFullYear()+"-"+pad(now.getMonth()+1)+"-"+pad(now.getDate());
  const tmrDate      = new Date(now); tmrDate.setDate(now.getDate()+1);
  const tmrStr       = tmrDate.getFullYear()+"-"+pad(tmrDate.getMonth()+1)+"-"+pad(tmrDate.getDate());
  const getMon       = d => { const dt=new Date(d); dt.setHours(0,0,0,0); const dy=dt.getDay(); dt.setDate(dt.getDate()-(dy===0?6:dy-1)); return dt; };
  const weekMon      = getMon(now);
  const weekSun      = new Date(weekMon); weekSun.setDate(weekMon.getDate()+6); weekSun.setHours(23,59,59,999);
  const inWeek       = d => { const dt=new Date(d+"T00:00:00"); return dt>=weekMon&&dt<=weekSun; };

  const resolveKey = n => callData[n]?n:Object.keys(callData).find(k=>norm(k)===n)||n;

  const aggCalls = (dayTest) => {
    let completed=0,noShow=0,cancelled=0,scheduled=0;
    csmNames.forEach(n => {
      Object.entries(callData[resolveKey(n)]||{}).forEach(([day,svcs]) => {
        if (!dayTest(day)) return;
        Object.values(svcs).forEach(d => { completed+=(d.completed||0); noShow+=(d.noShow||0); cancelled+=(d.cancelled||0); scheduled+=(d.scheduled||0); });
      });
    });
    const resolved=completed+noShow;
    return {completed,noShow,cancelled,scheduled,total:completed+noShow+cancelled+scheduled,resolved,
      compRate:resolved>0?completed/resolved:null, nsRate:resolved>0?noShow/resolved:null};
  };
  const today = aggCalls(d=>d===todayStr);
  const tmrw  = aggCalls(d=>d===tmrStr);
  const week  = aggCalls(dashDayTest);  // uses selected date filter

  const csmFiltered = csmNames.map(n => {
    const key=resolveKey(n);
    let s=0,c=0,ns=0,can=0;
    Object.entries(callData[key]||{}).forEach(([day,svcs])=>{
      if(!dashDayTest(day)) return;
      Object.values(svcs).forEach(d=>{s+=d.scheduled||0;c+=d.completed||0;ns+=d.noShow||0;can+=d.cancelled||0;});
    });
    return {name:n,scheduled:s,completed:c,noShow:ns,cancelled:can,total:s+c+ns+can};
  }).filter(r=>r.total>0).sort((a,b)=>b.total-a.total);
  const csmToday = csmNames.map(n => {
    const key=resolveKey(n); const dd=(callData[key]||{})[todayStr]||{};
    let s=0,c=0,ns=0,can=0;
    Object.values(dd).forEach(d=>{s+=d.scheduled||0;c+=d.completed||0;ns+=d.noShow||0;can+=d.cancelled||0;});
    return {name:n,scheduled:s,completed:c,noShow:ns,cancelled:can,total:s+c+ns+can};
  }).filter(r=>r.total>0).sort((a,b)=>b.total-a.total);

  // Q3 Book of Business — now sourced from the shared SF-based summary (same
  // data as the Book of Business tab), not the old Domo BOQ export. Net is
  // derived as cur-boq so all the downstream math below (which expects
  // boq+net=current) keeps working unchanged.
  const boqMap = {};
  (Array.isArray(sfBobRows)?sfBobRows:[]).forEach(([csmRaw, eid, acct, boq, cur, status]) => {
    if (!eid) return;
    const csmKey = normalizeSFCsmName(csmRaw);
    boqMap[eid] = {eid, csm:csmKey, acct, boq, net: cur-boq};
  });
  // Build a set of all normalized name variants for the filtered CSMs
  const csmNorms=new Set(csmNames.flatMap(n=>[norm(n),n.toLowerCase()].filter(Boolean)));

  // ── Fulfillment Items scoped to this view (own FIs OR onboarding forms) ────
  // No explicit "due date" field exists in the FI data (unlike Cadence's Due
  // Date/Time), so this isn't filtered by dashDateFilter the way calls/cadence
  // are — it shows everything currently open in scope, sorted worst-aging-first.
  const fiSource = (fiRows && fiRows.length>0) ? fiRows : (typeof FI_RAW !== "undefined" ? FI_RAW : []);
  const myFI = fiSource.filter(r => {
    if (!filterCoach && !filterCSM) return true;
    const fiN = norm(r.fiOwner)||r.fiOwner, ofN = norm(r.ofOwner)||r.ofOwner;
    return csmNorms.has((fiN||"").toLowerCase()) || csmNorms.has((ofN||"").toLowerCase());
  });
  const myFISocial  = myFI.filter(r=>r.fiType==="Social FI").length;
  const myFIWebsite = myFI.filter(r=>r.fiType==="Website FI").length;
  const myFIUrgent  = (typeof fiIsUrgent === "function" ? myFI.filter(fiIsUrgent) : []).sort((a,b)=>b.aging-a.aging);
  const myFIAging   = [...myFI].sort((a,b)=>b.aging-a.aging).slice(0,5);

  // ── CER processing — Q3 calendar quarter (Jul 1 – Sep 30) ──────────────────
  const cerQStart = new Date(now.getFullYear(), 6, 1);   // Jul 1
  const cerQEnd   = new Date(now.getFullYear(), 8, 30, 23, 59, 59); // Sep 30
  const inCerQ    = d => d instanceof Date && !isNaN(d) && d>=cerQStart && d<=cerQEnd;
  const parseDate = s => { if(!s) return null; const d=new Date(s); return isNaN(d)?null:d; };
  // Normalize coach name: strip spaces, lowercase
  const normCoach = n => String(n||"").replace(/\s/g,"").toLowerCase();
  const coachKeys = filterCoach ? new Set([normCoach(COACHES.find(c=>c.e===filterCoach)?.n||"")]) : null;
  const csmNameSet = new Set(csmNames.map(n=>norm(n)));

  const filterCER = (rows, dateField) => rows.filter(r => {
    const d = parseDate(r[dateField]||r["Form Start Date"]||r["Form End Date"]||"");
    if (!inCerQ(d)) return false;
    // Match by CSM owner first
    const owner = norm(String(r["Client Engagement Roadmap: Owner Name"]||r["Owner Name"]||"").trim());
    if (owner && csmNameSet.has(owner)) return true;
    // Fall back to coach name match
    const coach = normCoach(r["CSM Coach Name"]||r["Coach"]||"");
    if (coachKeys && coachKeys.has(coach)) return true;
    if (!filterCoach && !filterCSM) return true; // org view: include all
    return false;
  });

  const cerAssignedQ  = filterCER(cerAssigned,  "Form Start Date");
  const cerCompletedQ = filterCER(cerCompleted, "Form End Date");

  // Status breakdown from assigned rows (has full status field)
  const cerInProgress = cerAssignedQ.filter(r=>r["Status"]==="In Progress").length;
  const cerNew        = cerAssignedQ.filter(r=>r["Status"]==="New").length;
  const cerOnHold     = cerAssignedQ.filter(r=>r["Status"]==="On Hold").length;
  const cerCompRate   = cerAssignedQ.length>0 ? cerCompletedQ.length/cerAssignedQ.length : null;

  // ── Parse cadenceFull rows (needs csmNorms + dashDayTest, both defined above) ──
  const parseCadRow = r => {
    const assigned = String(r["Cadence Member: Assigned"]||r["Assigned"]||"").trim();
    const account  = String(r["Cadence Member: Account"]||r["Account"]||"").trim();
    const status   = String(r["Status"]||"").trim();
    const overdue  = String(r["Overdue"]||"").trim()==="1";
    const dateRaw  = String(r["Due Date/Time"]||r["Due Date"]||"").trim();
    let dueDate = null;
    if (dateRaw) { const d=new Date(dateRaw); if (!isNaN(d)) dueDate=d; }
    return {assigned:norm(assigned)||assigned, account, status, overdue, dueDate};
  };
  const myCadRows = (Array.isArray(cadenceFull)?cadenceFull:[]).map(parseCadRow).filter(r => {
    if (!r.assigned) return false;
    return csmNorms.has(r.assigned)||csmNorms.has(norm(r.assigned));
  });
  const toDayKey = d => d?d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0"):null;
  const cadDueInWindow     = myCadRows.filter(r=>r.status==="Open"&&r.dueDate&&dashDayTest(toDayKey(r.dueDate)));
  const cadCompleted       = myCadRows.filter(r=>r.status==="Completed"&&r.dueDate&&dashDayTest(toDayKey(r.dueDate)));
  const cadSkipped         = myCadRows.filter(r=>r.status==="Skipped"&&r.dueDate&&dashDayTest(toDayKey(r.dueDate)));
  const cadOpenAll         = myCadRows.filter(r=>r.status==="Open");
  const cadAccountsInWindow = new Set(cadDueInWindow.map(r=>r.account).filter(Boolean));

  const bobRows=Object.values(boqMap).filter(b=>{
    const bNorm=b.csm;
    return csmNorms.has(bNorm)||csmNorms.has(norm(bNorm));
  });
  const totalAccts=bobRows.length;
  const totalBoq=bobRows.reduce((s,b)=>s+b.boq,0);
  const totalCur=bobRows.reduce((s,b)=>s+b.boq+b.net,0);
  const totalRet=totalBoq>0?totalCur/totalBoq:null;
  const retColor=r=>r==null?"#808080":r>=0.9095?"#16a34a":r>=0.845?"#d97706":"#dc2626";

  const bobAlerts=[];
  let totalIncreaseCount=0, totalIncreaseMrr=0, totalDecreaseMrr=0, totalCancelMrr=0;
  bobRows.forEach(b=>{
    const cur=b.boq+b.net;
    const delta=cur-b.boq;
    if (b.boq>0&&cur<=0) { bobAlerts.push({csm:b.csm,acct:b.acct,type:"Cancel",boq:b.boq,cur:0}); totalCancelMrr+=b.boq; }
    else if (delta<0&&cur>0&&Math.abs(delta)>=0.5) { bobAlerts.push({csm:b.csm,acct:b.acct,type:"Decrease",boq:b.boq,cur}); totalDecreaseMrr+=Math.abs(delta); }
    else if (delta>0&&Math.abs(delta)>=0.5) { bobAlerts.push({csm:b.csm,acct:b.acct,type:"Increase",boq:b.boq,cur}); totalIncreaseCount++; totalIncreaseMrr+=delta; }
  });

  const cancelAlerts=[...bobAlerts];
  csmNames.forEach(n=>{
    const c=csms.find(x=>x.name===n); if(!c) return;
    (c.bobMch||[]).forEach(acct=>{ if(!cancelAlerts.some(a=>a.acct===acct)) cancelAlerts.push({csm:dispName(n),acct,type:"MC"}); });
    (c.bobBch||[]).forEach(acct=>{ if(!cancelAlerts.some(a=>a.acct===acct)) cancelAlerts.push({csm:dispName(n),acct,type:"BC"}); });
  });
  (Array.isArray(churnAlerts)?churnAlerts:[]).forEach(a=>{
    const matched=csms.find(c=>norm(c.name)===norm(a.csm||""));
    if(matched&&!cancelAlerts.some(x=>x.acct===(a.acct||a.account||"")))
      cancelAlerts.push({csm:dispName(matched.name),acct:a.acct||a.account||"",type:"Alert",mrr:a.mrr});
  });

  // Cadence summary from cadenceFull (replaces old csms[].cadCount)
  const cadTotal    = myCadRows.length;
  const cadDone     = cadCompleted.length;
  const cadPct      = cadTotal>0 ? cadDone/cadTotal : null;
  const overdueCSMs = csmNames.map(n => {
    const nNorm = norm(n)||n;
    const myOver = myCadRows.filter(r=>(r.assigned===nNorm||norm(r.assigned)===nNorm) && r.status==="Open" && r.overdue);
    return {name:n, overdueCount:myOver.length};
  }).filter(c=>c.overdueCount>0).sort((a,b)=>b.overdueCount-a.overdueCount);

  // Revenue: same logic as Revenue tab — filter rawRev by CSM, compute Q3 totals
  const revRows = rawRev.map(r => {
    const csmRaw = String(r["CSM Name"]||r["csm_name"]||r["Staff Name"]||"").trim();
    const csm = norm(csmRaw)||csmRaw;
    const mrr = parseFloat(String(r["MRR $ Added"]||r["MRR $"]||r["MRR"]||0).replace(/[$,]/g,""))||0;
    const otr = parseFloat(String(r["OTR $ Added"]||r["OTR $"]||r["OTR"]||0).replace(/[$,]/g,""))||0;
    const tot = parseFloat(String(r["Total Revenue Added"]||r["Total Revenue"]||r["Revenue"]||0).replace(/[$,]/g,""))||0;
    const nr  = (r["Non-Revenue Integrations"]||"").trim();
    const qtr = (r["Quarter for Consideration"]||r["Quarter"]||"").trim();
    return {csm, mrr, otr, tot, nr, qtr};
  }).filter(r => {
    if (!r.csm) return false;
    // Filter to Q3 2026
    if (r.qtr && !r.qtr.includes("Q3") && !r.qtr.includes("q3")) return false;
    return csmNorms.has(r.csm) || csmNorms.has(norm(r.csm));
  });
  const totalRevMrr = revRows.reduce((s,r)=>s+r.mrr,0);
  const totalRevOtr = revRows.reduce((s,r)=>s+r.otr,0);
  const totalRevTot = revRows.reduce((s,r)=>s+r.tot,0);
  const totalRevSubs = revRows.length;
  const mrrSubs = revRows.filter(r=>r.mrr>0).length;
  const otrSubs = revRows.filter(r=>r.otr>0).length;
  const nonRevSubs = revRows.filter(r=>r.nr).length;

  const card={background:"#fff",borderRadius:12,padding:"20px 24px",boxShadow:"0 1px 4px rgba(41,53,93,.07)",marginBottom:16};
  const lbl={fontSize:12,textTransform:"uppercase",color:"#808080",fontWeight:600,letterSpacing:"0.05em",marginBottom:8,display:"block"};
  const StatTile=({label,value,sub,col="#29355D",bar=null})=>(
    <div style={{background:"#fff",borderRadius:12,padding:"14px 18px",boxShadow:"0 1px 4px rgba(41,53,93,.07)",borderTop:"3px solid "+col}}>
      <div style={lbl}>{label}</div>
      <div style={{fontSize:24,fontWeight:700,color:col,lineHeight:1,marginBottom:4}}>{value}</div>
      {bar!=null&&<div style={{height:5,background:"rgba(0,0,0,.08)",borderRadius:3,overflow:"hidden",margin:"6px 0"}}><div style={{width:Math.min(bar*100,100).toFixed(1)+"%",height:"100%",background:col,borderRadius:3}}/></div>}
      {sub&&<div style={{fontSize:13,color:"#808080",marginTop:2}}>{sub}</div>}
    </div>
  );

  return (
    <div style={{maxWidth:1200,margin:"0 auto"}}>
      {/* Header */}
      <div style={{display:"flex",alignItems:"flex-start",justifyContent:"space-between",marginBottom:20,flexWrap:"wrap",gap:8}}>
        <div>
          <div style={{fontSize:22,fontWeight:700,color:"#29355D"}}>{contextIcon} {contextLabel}</div>
          <div style={{fontSize:12,color:"#808080",marginTop:3}}>{csms.length} CSM{csms.length!==1?"s":""} · {totalAccts} accounts · {now.toLocaleDateString("en-US",{weekday:"long",month:"long",day:"numeric",year:"numeric"})}</div>
        </div>
        {!filterCoach&&!filterCSM&&<div style={{fontSize:12,color:"#808080",background:"rgba(41,53,93,.05)",borderRadius:8,padding:"8px 14px",border:"0.5px solid rgba(41,53,93,.1)"}}>💡 Select a coach or CSM from the filters above to see their individual view</div>}
      </div>

      {/* Date filter pills */}
      <div style={{display:"flex",alignItems:"center",gap:6,marginBottom:16,flexWrap:"wrap"}}>
        {[["last_week","Last week"],["today","Today"],["this_week","This week"],["next_week","Next week"]
        ].map(([v,l])=>(
          <button key={v} onClick={()=>setDashDateFilter(v)}
            style={{padding:"5px 12px",borderRadius:20,border:"0.5px solid "+(dashDateFilter===v?"#29355D":"rgba(41,53,93,.2)"),
              background:dashDateFilter===v?"#29355D":"#fff",color:dashDateFilter===v?"#fff":"#808080",
              fontSize:12,fontWeight:dashDateFilter===v?600:400,cursor:"pointer",whiteSpace:"nowrap"}}>
            {l}
          </button>
        ))}

        <span style={{fontSize:13,color:"#808080",marginLeft:4}}>{dashLabel}</span>
      </div>



      {/* Activity cards: Calls | Cadence touchpoints | Clients worked | Fulfillment Items */}
      <div style={{display:"grid",gridTemplateColumns:"repeat(4,minmax(0,1fr))",gap:12,marginBottom:16}}>

        {/* Calls */}
        <div style={card}>
          <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:8,cursor:"pointer"}} onClick={()=>onNavigate("calls")}>
            <span style={lbl}>📞 Calls — {dashLabel}</span>
            <span style={{fontSize:12,color:"#5378FC",fontWeight:500}}>View details →</span>
          </div>
          <div style={{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:8,marginBottom:10}}>
            {[{l:"Booked",v:week.total,c:"var(--text-primary)"},{l:"Completed",v:week.completed,c:"#16a34a"},
              {l:"No Shows",v:week.noShow,c:week.noShow>0?"#dc2626":"var(--text-secondary)"},
              {l:"Cancelled",v:week.cancelled,c:week.cancelled>0?"#d97706":"var(--text-secondary)"}].map(m=>(
              <div key={m.l}><div style={{fontSize:12,color:"var(--text-secondary)",fontWeight:500,textTransform:"uppercase",marginBottom:3}}>{m.l}</div><div style={{fontSize:20,fontWeight:500,color:m.c}}>{m.v}</div></div>
            ))}
          </div>
          {week.compRate!=null&&<>
            <div style={{display:"flex",justifyContent:"space-between",marginBottom:4}}>
              <span style={{fontSize:13,color:"var(--text-secondary)"}}>Completion rate <span style={{fontSize:12,color:"var(--text-muted)",fontWeight:400}}>(of resolved)</span></span>
              <span style={{fontSize:13,fontWeight:500,color:cc(week.compRate)}}>{pp(week.compRate)}</span>
            </div>
            <div style={{height:5,background:"rgba(0,0,0,.08)",borderRadius:3,overflow:"hidden"}}>
              <div style={{width:(week.compRate*100).toFixed(1)+"%",height:"100%",background:cc(week.compRate),borderRadius:3}}/>
            </div>
            <div style={{fontSize:12,color:"var(--text-secondary)",marginTop:5}}>
              No-show: <span style={{color:nsc(week.nsRate),fontWeight:500}}>{pp(week.nsRate)}</span>
              {week.scheduled>0&&<span style={{color:"#5378FC",marginLeft:8}}>{week.scheduled} scheduled</span>}
            </div>
          </>}
          {week.total===0&&<div style={{fontSize:12,color:"var(--text-secondary)",textAlign:"center",padding:"8px 0"}}>No call data for this period</div>}
        </div>

        {/* Cadence touchpoints */}
        <div style={card}>
          <span style={lbl}>✅ Cadence touchpoints — {dashLabel}</span>
          <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:8}}>
            <div>
              <div style={{fontSize:12,color:"var(--text-secondary)",fontWeight:500,textTransform:"uppercase",marginBottom:3}}>Due</div>
              <div style={{fontSize:20,fontWeight:500,color:"var(--text-primary)"}}>{cadDueInWindow.length}</div>
            </div>
            <div>
              <div style={{fontSize:12,color:"var(--text-secondary)",fontWeight:500,textTransform:"uppercase",marginBottom:3}}>Completed</div>
              <div style={{fontSize:20,fontWeight:500,color:"#16a34a"}}>{cadCompleted.length}</div>
            </div>
            <div>
              <div style={{fontSize:12,color:"var(--text-secondary)",fontWeight:500,textTransform:"uppercase",marginBottom:3}}>Open</div>
              <div style={{fontSize:20,fontWeight:500,color:"var(--text-primary)"}}>{cadOpenAll.length}</div>
            </div>
          </div>
          {cadTotal===0&&<div style={{fontSize:12,color:"var(--text-secondary)",textAlign:"center",padding:"8px 0",marginTop:8}}>No cadence data loaded yet</div>}
        </div>

        {/* Clients touched */}
        <div style={card}>
          <span style={lbl}>👥 Clients touched — {dashLabel}</span>
          <div style={{marginBottom:8}}>
            <div style={{fontSize:12,color:"var(--text-secondary)",fontWeight:500,textTransform:"uppercase",marginBottom:3}}>Total touchpoints</div>
            <div style={{fontSize:32,fontWeight:500,color:"var(--text-primary)"}}>{week.total + cadDueInWindow.length}</div>
            <div style={{fontSize:13,color:"var(--text-secondary)",marginTop:4}}>calls + cadence due</div>
          </div>
          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8,marginTop:10,paddingTop:10,borderTop:"0.5px solid var(--border)"}}>
            <div>
              <div style={{fontSize:12,color:"var(--text-secondary)",fontWeight:500,textTransform:"uppercase",marginBottom:3}}>Calls</div>
              <div style={{fontSize:18,fontWeight:500,color:"#5378FC"}}>{week.total}</div>
            </div>
            <div>
              <div style={{fontSize:12,color:"var(--text-secondary)",fontWeight:500,textTransform:"uppercase",marginBottom:3}}>Cadence due</div>
              <div style={{fontSize:18,fontWeight:500,color:"#6366f1"}}>{cadDueInWindow.length}</div>
            </div>
          </div>
        </div>

        {/* Fulfillment Items */}
        <div style={card}>
          <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:8,cursor:"pointer"}} onClick={()=>onNavigate("fi")}>
            <span style={lbl}>📋 Fulfillment Items{myFIUrgent.length>0 && <span style={{marginLeft:6,fontSize:11,fontWeight:700,padding:"1px 6px",borderRadius:20,background:"#dc2626",color:"#fff"}}>🚨 {myFIUrgent.length}</span>}</span>
            <span style={{fontSize:12,color:"#5378FC",fontWeight:500}}>View details →</span>
          </div>
          <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:8,marginBottom:10}}>
            <div><div style={{fontSize:12,color:"var(--text-secondary)",fontWeight:500,textTransform:"uppercase",marginBottom:3}}>Total</div><div style={{fontSize:20,fontWeight:500,color:"var(--text-primary)"}}>{myFI.length}</div></div>
            <div><div style={{fontSize:12,color:"var(--text-secondary)",fontWeight:500,textTransform:"uppercase",marginBottom:3}}>Social</div><div style={{fontSize:20,fontWeight:500,color:"#d97706"}}>{myFISocial}</div></div>
            <div><div style={{fontSize:12,color:"var(--text-secondary)",fontWeight:500,textTransform:"uppercase",marginBottom:3}}>Website</div><div style={{fontSize:20,fontWeight:500,color:"#2a78d6"}}>{myFIWebsite}</div></div>
          </div>
          {myFIUrgent.length>0 ? (
            <div style={{fontSize:11,color:"#dc2626",marginTop:6,fontWeight:600}}>
              🚨 {myFIUrgent[0].account} — {FI_ALWAYS_URGENT_FUNCTIONS.has(myFIUrgent[0].func) ? "Unengaged" : myFIUrgent[0].func+", "+myFIUrgent[0].aging.toFixed(1)+"d"}
              {myFIUrgent.length>1 && <span style={{color:"#991b1b",fontWeight:400}}> (+{myFIUrgent.length-1} more urgent)</span>}
            </div>
          ) : myFIAging.length>0 ? (
            <div style={{fontSize:11,color:"var(--text-secondary)",marginTop:6}}>
              Oldest in current function: <b style={{color:"#29355D"}}>{myFIAging[0].account}</b> ({myFIAging[0].aging.toFixed(1)}d)
            </div>
          ) : (
            <div style={{fontSize:12,color:"var(--text-secondary)",textAlign:"center",padding:"8px 0"}}>No Fulfillment Items in scope</div>
          )}
        </div>

      </div>



      {/* CER card */}
      <div style={card}>
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:16,cursor:"pointer"}} onClick={()=>onNavigate("cers")}>
          <div style={{display:"flex",alignItems:"center",gap:8}}>
            <span style={{fontSize:13}}>📋</span>
            <span style={lbl}>Client Engagement Roadmaps — Q3 {now.getFullYear()}</span>
          </div>
          <div style={{display:"flex",alignItems:"center",gap:10}}>
            <span style={{fontSize:13,color:"var(--text-secondary)",background:"var(--surface-1)",border:"0.5px solid var(--border)",padding:"2px 10px",borderRadius:20}}>Jul 1 – Sep 30</span>
            <span style={{fontSize:12,color:"#5378FC",fontWeight:500}}>View details →</span>
          </div>
        </div>
        {cerAssignedQ.length>0||cerCompletedQ.length>0?(
          <>
            <div style={{display:"grid",gridTemplateColumns:"repeat(3,minmax(0,1fr))",gap:12,marginBottom:14}}>
              <div style={{background:"var(--surface-1)",border:"0.5px solid var(--border)",borderTop:"3px solid #29355D",borderRadius:12,padding:"12px 16px"}}>
                <div style={{fontSize:12,color:"var(--text-secondary)",fontWeight:500,textTransform:"uppercase",marginBottom:4}}>Assigned</div>
                <div style={{fontSize:24,fontWeight:500,color:"var(--text-primary)",lineHeight:1,marginBottom:3}}>{cerAssignedQ.length}</div>
                <div style={{fontSize:12,color:"var(--text-muted)"}}>form start in Q3</div>
              </div>
              <div style={{background:"var(--surface-1)",border:"0.5px solid var(--border)",borderTop:"3px solid #16a34a",borderRadius:12,padding:"12px 16px"}}>
                <div style={{fontSize:12,color:"var(--text-secondary)",fontWeight:500,textTransform:"uppercase",marginBottom:4}}>Completed</div>
                <div style={{fontSize:24,fontWeight:500,color:"#16a34a",lineHeight:1,marginBottom:3}}>{cerCompletedQ.length}</div>
                <div style={{fontSize:12,color:"var(--text-muted)"}}>form end in Q3</div>
              </div>
              <div style={{background:"var(--surface-1)",border:"0.5px solid var(--border)",borderTop:"3px solid #d97706",borderRadius:12,padding:"12px 16px"}}>
                <div style={{fontSize:12,color:"var(--text-secondary)",fontWeight:500,textTransform:"uppercase",marginBottom:4}}>In progress / New</div>
                <div style={{fontSize:24,fontWeight:500,color:"#d97706",lineHeight:1,marginBottom:3}}>{cerInProgress+cerNew+cerOnHold}</div>
                <div style={{fontSize:12,color:"var(--text-muted)"}}>open + on hold + new</div>
              </div>
            </div>
            <div style={{borderTop:"0.5px solid rgba(41,53,93,.08)",paddingTop:12,display:"flex",gap:8,flexWrap:"wrap"}}>
              {cerCompletedQ.length>0&&<span style={{display:"inline-flex",alignItems:"center",gap:4,fontSize:13,padding:"3px 10px",borderRadius:20,background:"rgba(22,163,74,.08)",color:"#15803d",border:"0.5px solid rgba(22,163,74,.2)"}}>✓ Completed {cerCompletedQ.length}</span>}
              {cerInProgress>0&&<span style={{display:"inline-flex",alignItems:"center",gap:4,fontSize:13,padding:"3px 10px",borderRadius:20,background:"rgba(217,119,6,.08)",color:"#b45309",border:"0.5px solid rgba(217,119,6,.2)"}}>⟳ In progress {cerInProgress}</span>}
              {cerNew>0&&<span style={{display:"inline-flex",alignItems:"center",gap:4,fontSize:13,padding:"3px 10px",borderRadius:20,background:"rgba(41,53,93,.06)",color:"#808080",border:"0.5px solid rgba(41,53,93,.15)"}}>◦ New {cerNew}</span>}
              {cerOnHold>0&&<span style={{display:"inline-flex",alignItems:"center",gap:4,fontSize:13,padding:"3px 10px",borderRadius:20,background:"rgba(41,53,93,.06)",color:"#808080",border:"0.5px solid rgba(41,53,93,.15)"}}>⏸ On hold {cerOnHold}</span>}
            </div>
          </>
        ):(
          <div style={{fontSize:12,color:"var(--text-secondary)",textAlign:"center",padding:"16px 0"}}>No CER data loaded yet</div>
        )}
      </div>

      {/* Q3 Book of Business */}
      <div style={{...card,marginBottom:16}}>
          <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:8,cursor:"pointer"}} onClick={()=>{onSetBobTab("sfpreview");onNavigate("bob");}}>
            <span style={lbl}>📋 Q3 Book of Business</span>
            <span style={{fontSize:12,color:"#5378FC",fontWeight:500}}>View details →</span>
          </div>
          {totalAccts>0?(<>
            {/* Top row: key metrics */}
            <div style={{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:10,marginBottom:14}}>
              <div><div style={{fontSize:12,color:"#808080",fontWeight:500,textTransform:"uppercase",marginBottom:3}}>Accounts</div><div style={{fontSize:22,fontWeight:700,color:"#29355D"}}>{totalAccts}</div></div>
              <div><div style={{fontSize:12,color:"#808080",fontWeight:500,textTransform:"uppercase",marginBottom:3}}>Retention</div><div style={{fontSize:22,fontWeight:700,color:retColor(totalRet)}}>{totalRet!=null?(totalRet*100).toFixed(1)+"%":"--"}</div><div style={{fontSize:12,color:"#808080"}}>goal 91%</div></div>
              <div style={{padding:"8px 10px",background:"rgba(41,53,93,.04)",borderRadius:8}}><div style={{fontSize:12,color:"#808080",marginBottom:2}}>BOQ</div><div style={{fontSize:16,fontWeight:700,color:"#5378FC"}}>{fk(totalBoq)}</div></div>
              <div style={{padding:"8px 10px",background:"rgba(41,53,93,.04)",borderRadius:8}}><div style={{fontSize:12,color:"#808080",marginBottom:2}}>Current MRR</div><div style={{fontSize:16,fontWeight:700,color:"#29355D"}}>{fk(totalCur)}</div></div>
            </div>
            {/* Account Increases, Decreases & Cancels */}
            <div style={{marginBottom:8}}><div style={{fontSize:12,textTransform:"uppercase",color:"#808080",fontWeight:600,letterSpacing:"0.05em"}}>Account Increases, Decreases, &amp; Cancels</div><div style={{fontSize:12,color:"#aaa",marginTop:2}}>Change in MRR during current quarter</div></div>
            <div style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:10,marginBottom:12}}>
              {/* Increases — green */}
              <div style={{padding:"12px 14px",background:"rgba(22,163,74,.06)",borderRadius:8,border:"0.5px solid rgba(22,163,74,.25)"}}>
                <div style={{fontSize:12,color:"#15803d",fontWeight:600,textTransform:"uppercase",marginBottom:6,letterSpacing:"0.04em"}}>↑ Account Increases</div>
                <div style={{fontSize:22,fontWeight:700,color:"#15803d",marginBottom:2}}>{totalIncreaseCount}</div>
                <div style={{fontSize:14,fontWeight:700,color:"#15803d",marginBottom:6}}>+{fk(totalIncreaseMrr)}</div>
                <div style={{fontSize:12,color:"#166534"}}>accounts above BOQ</div>
                {bobAlerts.filter(a=>a.type==="Increase").length>0&&(
                  <div style={{display:"flex",flexDirection:"column",gap:3,maxHeight:72,overflowY:"auto",marginTop:8}}>
                    {bobAlerts.filter(a=>a.type==="Increase").slice(0,4).map((a,i)=>(
                      <div key={i} style={{fontSize:12,color:"#166534"}}>{a.acct} <span style={{fontWeight:600}}>{fk(a.boq)}→{fk(a.cur)}</span></div>
                    ))}
                    {bobAlerts.filter(a=>a.type==="Increase").length>4&&<div style={{fontSize:12,color:"#166534"}}>+{bobAlerts.filter(a=>a.type==="Increase").length-4} more</div>}
                  </div>
                )}
              </div>
              {/* Decreases — amber */}
              <div style={{padding:"12px 14px",background:"rgba(217,119,6,.06)",borderRadius:8,border:"0.5px solid rgba(217,119,6,.25)"}}>
                <div style={{fontSize:12,color:"#b45309",fontWeight:600,textTransform:"uppercase",marginBottom:6,letterSpacing:"0.04em"}}>↓ Account Decreases</div>
                <div style={{fontSize:22,fontWeight:700,color:"#b45309",marginBottom:2}}>{bobAlerts.filter(a=>a.type==="Decrease").length}</div>
                <div style={{fontSize:14,fontWeight:700,color:"#b45309",marginBottom:6}}>-{fk(totalDecreaseMrr)}</div>
                <div style={{fontSize:12,color:"#92400e"}}>accounts below BOQ</div>
                {bobAlerts.filter(a=>a.type==="Decrease").length>0&&(
                  <div style={{display:"flex",flexDirection:"column",gap:3,maxHeight:72,overflowY:"auto",marginTop:8}}>
                    {bobAlerts.filter(a=>a.type==="Decrease").slice(0,4).map((a,i)=>(
                      <div key={i} style={{fontSize:12,color:"#92400e"}}>{a.acct} <span style={{fontWeight:600}}>{fk(a.boq)}→{fk(a.cur)}</span></div>
                    ))}
                    {bobAlerts.filter(a=>a.type==="Decrease").length>4&&<div style={{fontSize:12,color:"#92400e"}}>+{bobAlerts.filter(a=>a.type==="Decrease").length-4} more</div>}
                  </div>
                )}
              </div>
              {/* Cancels — red */}
              <div style={{padding:"12px 14px",background:"rgba(220,38,38,.06)",borderRadius:8,border:"0.5px solid rgba(220,38,38,.25)"}}>
                <div style={{fontSize:12,color:"#b91c1c",fontWeight:600,textTransform:"uppercase",marginBottom:6,letterSpacing:"0.04em"}}>✕ Account Cancels</div>
                <div style={{fontSize:22,fontWeight:700,color:"#b91c1c",marginBottom:2}}>{bobAlerts.filter(a=>a.type==="Cancel").length}</div>
                <div style={{fontSize:14,fontWeight:700,color:"#b91c1c",marginBottom:6}}>-{fk(totalCancelMrr)}</div>
                <div style={{fontSize:12,color:"#991b1b"}}>accounts churned</div>
                {bobAlerts.filter(a=>a.type==="Cancel").length>0&&(
                  <div style={{display:"flex",flexDirection:"column",gap:3,maxHeight:72,overflowY:"auto",marginTop:8}}>
                    {bobAlerts.filter(a=>a.type==="Cancel").slice(0,4).map((a,i)=>(
                      <div key={i} style={{fontSize:12,color:"#991b1b"}}>{a.acct} <span style={{fontWeight:600}}>{fk(a.boq)}</span></div>
                    ))}
                    {bobAlerts.filter(a=>a.type==="Cancel").length>4&&<div style={{fontSize:12,color:"#991b1b"}}>+{bobAlerts.filter(a=>a.type==="Cancel").length-4} more</div>}
                  </div>
                )}
              </div>
            </div>
            {/* Revenue Recommendations — Q3 (no daily date available yet in source) */}
            {totalRevTot>0&&(
              <div style={{padding:"12px 14px",background:"rgba(255,80,0,.05)",borderRadius:8,border:"0.5px solid rgba(255,80,0,.2)"}}>
                <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:8}}>
                  <div style={{fontSize:12,color:"#c2410c",fontWeight:600,textTransform:"uppercase",letterSpacing:"0.04em"}}>💡 Revenue upgrades submitted by CSM — Q3</div>
                  <div style={{fontSize:14,fontWeight:700,color:"#FF5000"}}>+{fd(totalRevTot)}</div>
                </div>
                <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:8}}>
                  <div style={{padding:"6px 10px",background:"rgba(255,80,0,.07)",borderRadius:6}}>
                    <div style={{fontSize:12,color:"#c2410c",marginBottom:2}}>MRR Added</div>
                    <div style={{fontSize:13,fontWeight:700,color:"#FF5000"}}>{fd(totalRevMrr)}</div>
                    <div style={{fontSize:12,color:"#9a3412"}}>{mrrSubs} sub{mrrSubs!==1?"s":""}</div>
                  </div>
                  <div style={{padding:"6px 10px",background:"rgba(255,80,0,.07)",borderRadius:6}}>
                    <div style={{fontSize:12,color:"#c2410c",marginBottom:2}}>One-Time</div>
                    <div style={{fontSize:13,fontWeight:700,color:"#FF5000"}}>{fd(totalRevOtr)}</div>
                    <div style={{fontSize:12,color:"#9a3412"}}>{otrSubs} sub{otrSubs!==1?"s":""}</div>
                  </div>
                  <div style={{padding:"6px 10px",background:"rgba(255,80,0,.07)",borderRadius:6}}>
                    <div style={{fontSize:12,color:"#c2410c",marginBottom:2}}>Non-Revenue</div>
                    <div style={{fontSize:13,fontWeight:700,color:"#FF5000"}}>{nonRevSubs}</div>
                    <div style={{fontSize:12,color:"#9a3412"}}>integrations</div>
                  </div>
                </div>
                <div style={{fontSize:12,color:"#9a3412",marginTop:6}}>Daily breakdown available once a submission date is added to the revenue form</div>
              </div>
            )}
          </>):<div style={{fontSize:12,color:"#808080",textAlign:"center",padding:"12px 0"}}>No Q3 BoB data loaded yet</div>}
        </div>

      {/* Cancel/decrease alerts */}
      {cancelAlerts.length>0&&(
        <div style={{...card,borderLeft:"4px solid #dc2626"}}>
          <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:10}}>
            <span style={{fontSize:16}}>🚨</span>
            <div>
              <span style={lbl}>Account Increases, Decreases, &amp; Cancels</span>
              <div style={{fontSize:12,color:"#aaa",marginTop:2,marginBottom:0}}>Change in MRR during current quarter</div>
            </div>
            <span id="alert-badge" style={{marginLeft:"auto",fontSize:13,fontWeight:600,padding:"2px 10px",borderRadius:20,
              background:alertFilter==="increase"?"rgba(22,163,74,.12)":alertFilter==="decrease"?"rgba(217,119,6,.12)":alertFilter==="cancel"?"rgba(220,38,38,.12)":"rgba(41,53,93,.06)",
              color:alertFilter==="increase"?"#15803d":alertFilter==="decrease"?"#b45309":alertFilter==="cancel"?"#991b1b":"#808080",
              border:"0.5px solid "+(alertFilter==="increase"?"rgba(22,163,74,.25)":alertFilter==="decrease"?"rgba(217,119,6,.25)":alertFilter==="cancel"?"rgba(220,38,38,.25)":"rgba(41,53,93,.15)")}}>
              {alertFilter==="increase"?cancelAlerts.filter(a=>a.type==="Increase").length:alertFilter==="decrease"?cancelAlerts.filter(a=>a.type==="Decrease").length:alertFilter==="cancel"?cancelAlerts.filter(a=>a.type==="Cancel"||a.type==="MC"||a.type==="BC"||a.type==="Alert").length:cancelAlerts.length} account{(alertFilter==="increase"?cancelAlerts.filter(a=>a.type==="Increase").length:alertFilter==="decrease"?cancelAlerts.filter(a=>a.type==="Decrease").length:alertFilter==="cancel"?cancelAlerts.filter(a=>a.type==="Cancel"||a.type==="MC"||a.type==="BC"||a.type==="Alert").length:cancelAlerts.length)!==1?"s":""}</span>
          </div>
          {(()=>{
            const filtered = alertFilter==="all" ? cancelAlerts :
              cancelAlerts.filter(a => {
                if (alertFilter==="increase") return a.type==="Increase";
                if (alertFilter==="decrease") return a.type==="Decrease";
                if (alertFilter==="cancel")   return a.type==="Cancel"||a.type==="MC"||a.type==="BC"||a.type==="Alert";
                return true;
              });
            return (<>
              <div style={{display:"flex",gap:6,marginBottom:14,flexWrap:"wrap"}}>
                {[["all","All"],["increase","Increases"],["decrease","Decreases"],["cancel","Cancels"]].map(([v,l])=>(
                  <button key={v} onClick={()=>setAlertFilter(v)}
                    style={{padding:"3px 12px",borderRadius:20,border:"0.5px solid "+(
                      v==="increase"?"rgba(22,163,74,.4)":v==="decrease"?"rgba(217,119,6,.4)":v==="cancel"?"rgba(220,38,38,.4)":"rgba(41,53,93,.2)"
                    ),background:alertFilter===v?(
                      v==="increase"?"rgba(22,163,74,.12)":v==="decrease"?"rgba(217,119,6,.12)":v==="cancel"?"rgba(220,38,38,.12)":"#29355D"
                    ):"#fff",
                    color:alertFilter===v?(
                      v==="increase"?"#15803d":v==="decrease"?"#b45309":v==="cancel"?"#991b1b":"#fff"
                    ):(v==="increase"?"#15803d":v==="decrease"?"#b45309":v==="cancel"?"#991b1b":"#808080"),
                    fontSize:13,fontWeight:alertFilter===v?600:400,cursor:"pointer"}}>
                    {l}
                  </button>
                ))}
              </div>
              <div style={{display:"flex",flexDirection:"column",gap:8}}>
                {filtered.slice(0,30).map((a,i)=>{
                  const isInc = a.type==="Increase";
                  const isDec = a.type==="Decrease";
                  const bg    = isInc?"rgba(22,163,74,.06)":isDec?"rgba(217,119,6,.06)":"rgba(220,38,38,.06)";
                  const bdr   = isInc?"rgba(22,163,74,.25)":isDec?"rgba(217,119,6,.25)":"rgba(220,38,38,.2)";
                  const badgeBg  = isInc?"rgba(22,163,74,.12)":isDec?"rgba(217,119,6,.12)":"rgba(220,38,38,.12)";
                  const badgeCol = isInc?"#15803d":isDec?"#b45309":"#991b1b";
                  return (
                    <div key={i} style={{display:"flex",alignItems:"center",gap:12,padding:"10px 14px",background:bg,borderRadius:8,border:"0.5px solid "+bdr}}>
                      <div style={{flex:1}}>
                        <div style={{fontSize:13,fontWeight:600,color:"#29355D"}}>{a.acct||"Unknown account"}</div>
                        <div style={{fontSize:13,color:"#808080",marginTop:2}}>{!filterCSM&&`${dispName(a.csm)} · `}{a.boq!=null&&`BOQ: ${fk(a.boq)}`}{a.cur!=null&&a.cur>0&&` → ${fk(a.cur)}`}{a.mrr&&`${fk(a.mrr)}/mo`}</div>
                      </div>
                      <span style={{fontSize:12,fontWeight:600,padding:"2px 8px",borderRadius:20,background:badgeBg,color:badgeCol}}>{a.type}</span>
                    </div>
                  );
                })}
                {filtered.length>30&&<div style={{fontSize:13,color:"#808080",textAlign:"center"}}>+{filtered.length-30} more</div>}
                {filtered.length===0&&<div style={{fontSize:12,color:"#808080",textAlign:"center",padding:"8px 0"}}>No {alertFilter} accounts</div>}
              </div>
            </>);
          })()}
        </div>
      )}

      {/* Today by CSM */}
      {!filterCSM&&csmFiltered.length>0&&(
        <div style={card}>
          <span style={lbl}>📋 Activity by CSM — {dashLabel}</span>
          <table style={{width:"100%",borderCollapse:"collapse",fontSize:12}}>
            <thead><tr>{[["CSM","left","#808080"],["Scheduled","right","#5378FC"],["Completed","right","#16a34a"],["No Shows","right","#dc2626"],["Cancelled","right","#d97706"]].map(([h,a,c])=>(<th key={h} style={{padding:"0 8px 8px 0",textAlign:a,fontSize:12,textTransform:"uppercase",color:c,fontWeight:500,borderBottom:"0.5px solid rgba(41,53,93,.08)"}}>{h}</th>))}</tr></thead>
            <tbody>{csmFiltered.map(r=>(<tr key={r.name}>
              <td style={{padding:"8px 8px 8px 0",borderBottom:"0.5px solid rgba(41,53,93,.05)",fontWeight:500,color:"#29355D"}}>{dispName(r.name)}</td>
              <td style={{padding:"8px 8px 8px 0",borderBottom:"0.5px solid rgba(41,53,93,.05)",textAlign:"right",color:r.scheduled>0?"#5378FC":"#ccc",fontWeight:r.scheduled>0?600:400}}>{r.scheduled||"—"}</td>
              <td style={{padding:"8px 8px 8px 0",borderBottom:"0.5px solid rgba(41,53,93,.05)",textAlign:"right",color:r.completed>0?"#16a34a":"#ccc",fontWeight:r.completed>0?600:400}}>{r.completed||"—"}</td>
              <td style={{padding:"8px 8px 8px 0",borderBottom:"0.5px solid rgba(41,53,93,.05)",textAlign:"right",color:r.noShow>0?"#dc2626":"#ccc"}}>{r.noShow||"—"}</td>
              <td style={{padding:"8px 8px 8px 0",borderBottom:"0.5px solid rgba(41,53,93,.05)",textAlign:"right",color:r.cancelled>0?"#d97706":"#ccc"}}>{r.cancelled||"—"}</td>
            </tr>))}</tbody>
          </table>
        </div>
      )}
    </div>
  );
}
// ═══════════════════════════════════════════════════════════════════════════


// ═══════════════════════════════════════════════════════════════════════════
// CER VIEW — Client Engagement Roadmaps tab
// ═══════════════════════════════════════════════════════════════════════════
function CERView({cerAssigned=[], filterCoach="", filterCSM=""}) {
  const [cerDateFilter, setCerDateFilter] = React.useState("quarter");
  const [cerStatusFilter, setCerStatusFilter] = React.useState("all");
  const [cerSort, setCerSort] = React.useState({col:"assigned", dir:"desc"});
  const [cerExpanded, setCerExpanded] = React.useState(null);
  const [cerAcctSort, setCerAcctSort] = React.useState({col:"date", dir:"desc"});

  const now = new Date();

  // ── Date boundaries ──
  const thisMonthStart = new Date(now.getFullYear(), now.getMonth(), 1);
  const thisMonthEnd   = new Date(now.getFullYear(), now.getMonth()+1, 0, 23, 59, 59);
  const thisQtrM       = Math.floor(now.getMonth()/3)*3;
  const thisQtrStart   = new Date(now.getFullYear(), thisQtrM, 1);
  const thisQtrEnd     = new Date(now.getFullYear(), thisQtrM+3, 0, 23, 59, 59);
  const thisYearStart  = new Date(now.getFullYear(), 0, 1);
  const thisYearEnd    = new Date(now.getFullYear(), 11, 31, 23, 59, 59);

  const dateRange = cerDateFilter==="month"  ? [thisMonthStart, thisMonthEnd]
                  : cerDateFilter==="quarter" ? [thisQtrStart,   thisQtrEnd]
                  :                             [thisYearStart,  thisYearEnd];

  const dateLabel = cerDateFilter==="month"
    ? now.toLocaleDateString("en-US",{month:"long",year:"numeric"})
    : cerDateFilter==="quarter"
      ? `Q${Math.floor(now.getMonth()/3)+1} ${now.getFullYear()} (${thisQtrStart.toLocaleDateString("en-US",{month:"short",day:"numeric"})} – ${thisQtrEnd.toLocaleDateString("en-US",{month:"short",day:"numeric"})})`
      : `${now.getFullYear()}`;

  const parseD = s => { if(!s) return null; const d=new Date(s); return isNaN(d)?null:d; };
  const inRange = d => d && d>=dateRange[0] && d<=dateRange[1];

  // ── Filter rows by date (Form Start Date) + coach/CSM ──
  const lk2 = n => { const nn=norm(n); return ROSTER[nn]||null; };
  const filteredRows = cerAssigned.filter(r => {
    const d = parseD(r["Form Start Date"]);
    if (!inRange(d)) return false;
    const owner = String(r["Client Engagement Roadmap: Owner Name"]||"").trim();
    if (filterCSM) return norm(owner)===norm(filterCSM);
    if (filterCoach) {
      const info = lk2(owner);
      return info && info.c === filterCoach;
    }
    return true;
  });

  // Status helper
  const getStatus = r => {
    const s = String(r["Status"]||"").trim();
    if (s==="Completed") return "completed";
    if (s==="In Progress") return "inprogress";
    return "new";
  };

  // Apply status filter
  const visibleRows = cerStatusFilter==="all" ? filteredRows
    : filteredRows.filter(r => getStatus(r)===cerStatusFilter);

  // ── Summary counts from filteredRows (not status-filtered) ──
  const totalAssigned   = filteredRows.length;
  const totalCompleted  = filteredRows.filter(r=>getStatus(r)==="completed").length;
  const totalInProgress = filteredRows.filter(r=>getStatus(r)==="inprogress").length;
  const totalNew        = filteredRows.filter(r=>getStatus(r)==="new").length;

  // ── Group by CSM ──
  const byCSM = {};
  visibleRows.forEach(r => {
    const csm = String(r["Client Engagement Roadmap: Owner Name"]||"").trim();
    if (!byCSM[csm]) byCSM[csm] = {name:csm, rows:[], assigned:0, completed:0, inprogress:0, newCount:0};
    byCSM[csm].rows.push(r);
    byCSM[csm].assigned++;
    const s = getStatus(r);
    if (s==="completed")  byCSM[csm].completed++;
    if (s==="inprogress") byCSM[csm].inprogress++;
    if (s==="new")        byCSM[csm].newCount++;
  });

  // ── Sort CSM rows ──
  const csmRows = Object.values(byCSM).sort((a,b) => {
    const dir = cerSort.dir==="asc" ? 1 : -1;
    if (cerSort.col==="csm")        return dir*(a.name.localeCompare(b.name));
    if (cerSort.col==="assigned")   return dir*(a.assigned-b.assigned);
    if (cerSort.col==="completed")  return dir*(a.completed-b.completed);
    if (cerSort.col==="inprogress") return dir*(a.inprogress-b.inprogress);
    if (cerSort.col==="new")        return dir*(a.newCount-b.newCount);
    return 0;
  });

  const sortCol = (col) => {
    setCerSort(s => s.col===col ? {col, dir:s.dir==="asc"?"desc":"asc"} : {col, dir:"desc"});
  };

  const sortIcon = col => cerSort.col===col ? (cerSort.dir==="desc"?"↓":"↑") : "↕";

  // ── Sort account rows ──
  const sortAccts = (rows) => [...rows].sort((a,b) => {
    const dir = cerAcctSort.dir==="asc" ? 1 : -1;
    if (cerAcctSort.col==="date") {
      const da = parseD(a["Form Start Date"])||new Date(0);
      const db = parseD(b["Form Start Date"])||new Date(0);
      return dir*(da-db);
    }
    if (cerAcctSort.col==="acct") return dir*(String(a["Account"]||"").localeCompare(String(b["Account"]||"")));
    if (cerAcctSort.col==="status") return dir*(getStatus(a).localeCompare(getStatus(b)));
    return 0;
  });

  const sortAcct = col => setCerAcctSort(s => s.col===col ? {col, dir:s.dir==="asc"?"desc":"asc"} : {col, dir:"desc"});
  const sortAcctIcon = col => cerAcctSort.col===col ? (cerAcctSort.dir==="desc"?"↓":"↑") : "↕";

  const fmtDate = s => {
    const d = parseD(s); if(!d) return "—";
    return d.toLocaleDateString("en-US",{month:"short",day:"numeric",year:"numeric"});
  };

  const statusPill = s => {
    if (s==="completed")  return <span style={{fontSize:12,padding:"2px 8px",borderRadius:20,background:"rgba(22,163,74,.08)",color:"#15803d",border:"0.5px solid rgba(22,163,74,.2)",fontWeight:500}}>Completed</span>;
    if (s==="inprogress") return <span style={{fontSize:12,padding:"2px 8px",borderRadius:20,background:"rgba(217,119,6,.08)",color:"#b45309",border:"0.5px solid rgba(217,119,6,.2)",fontWeight:500}}>In progress</span>;
    return <span style={{fontSize:12,padding:"2px 8px",borderRadius:20,background:"rgba(41,53,93,.06)",color:"#808080",border:"0.5px solid rgba(41,53,93,.15)",fontWeight:500}}>New</span>;
  };

  const S = {
    card:{background:"#fff",borderRadius:12,padding:"20px 24px",boxShadow:"0 1px 4px rgba(41,53,93,.07)",marginBottom:16},
    th:{padding:"9px 12px",textAlign:"left",fontSize:12,textTransform:"uppercase",color:"#808080",fontWeight:500,letterSpacing:"0.05em",borderBottom:"0.5px solid rgba(41,53,93,.08)",cursor:"pointer",whiteSpace:"nowrap",userSelect:"none"},
    td:{padding:"10px 12px",borderBottom:"0.5px solid rgba(41,53,93,.05)",color:"#29355D"},
  };

  // ── Export CSV ──
  const exportCSV = () => {
    const rows = [["CSM","Account","Form Start Date","Status"]];
    csmRows.forEach(g => sortAccts(g.rows).forEach(r => {
      rows.push([g.name, r["Account"]||"", fmtDate(r["Form Start Date"]), r["Status"]||""]);
    }));
    const csv = rows.map(r=>r.map(c=>`"${String(c).replace(/"/g,'""')}"`).join(",")).join("\n");
    const a = document.createElement("a");
    a.href = "data:text/csv;charset=utf-8,"+encodeURIComponent(csvContent);
    a.download = `CERs_${dateLabel.replace(/\s/g,"_")}.csv`;
    a.click();
  };

  return (
    <div style={{maxWidth:1200,margin:"0 auto"}}>

      {/* Header */}
      <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:16,flexWrap:"wrap",gap:8}}>
        <div>
          <div style={{fontSize:18,fontWeight:600,color:"#29355D"}}>📋 Client Engagement Roadmaps</div>
          <div style={{fontSize:12,color:"#808080",marginTop:2}}>{dateLabel} · {totalAssigned} assigned</div>
        </div>
        <button onClick={exportCSV} style={{fontSize:12,padding:"6px 14px",borderRadius:8,border:"0.5px solid rgba(41,53,93,.2)",background:"#fff",color:"#29355D",cursor:"pointer",fontWeight:500}}>↓ Export CSV</button>
      </div>

      {/* Summary tiles */}
      <div style={{display:"grid",gridTemplateColumns:"repeat(4,minmax(0,1fr))",gap:10,marginBottom:16}}>
        {[
          {l:"Assigned",   v:totalAssigned,   col:"#29355D", sub:"form start date"},
          {l:"Completed",  v:totalCompleted,  col:"#16a34a", sub:"status completed"},
          {l:"In progress",v:totalInProgress, col:"#d97706", sub:"open + on hold"},
          {l:"New",        v:totalNew,        col:"#808080", sub:"not yet started"},
        ].map(t=>(
          <div key={t.l} style={{background:"#fff",border:"0.5px solid rgba(41,53,93,.1)",borderTop:"3px solid "+t.col,borderRadius:12,padding:"12px 16px",boxShadow:"0 1px 4px rgba(41,53,93,.05)"}}>
            <div style={{fontSize:12,color:"#808080",textTransform:"uppercase",fontWeight:500,marginBottom:4}}>{t.l}</div>
            <div style={{fontSize:24,fontWeight:700,color:t.col,marginBottom:3}}>{t.v}</div>
            <div style={{fontSize:12,color:"#aaa"}}>{t.sub}</div>
          </div>
        ))}
      </div>

      {/* Date + status filters */}
      <div style={{display:"flex",gap:6,marginBottom:14,flexWrap:"wrap",alignItems:"center"}}>
        {[["month","This month"],["quarter","This quarter"],["year","This year"]].map(([v,l])=>(
          <button key={v} onClick={()=>setCerDateFilter(v)}
            style={{padding:"4px 14px",borderRadius:20,border:"0.5px solid "+(cerDateFilter===v?"#29355D":"rgba(41,53,93,.2)"),
              background:cerDateFilter===v?"#29355D":"#fff",color:cerDateFilter===v?"#fff":"#808080",
              fontSize:12,fontWeight:cerDateFilter===v?500:400,cursor:"pointer"}}>
            {l}
          </button>
        ))}
        <div style={{width:1,height:20,background:"rgba(41,53,93,.15)",margin:"0 4px"}}/>
        {[["all","All"],["completed","Completed"],["inprogress","In progress"],["new","New"]].map(([v,l])=>(
          <button key={v} onClick={()=>setCerStatusFilter(v)}
            style={{padding:"4px 12px",borderRadius:20,cursor:"pointer",fontSize:12,fontWeight:cerStatusFilter===v?500:400,
              border:"0.5px solid "+(v==="completed"?"rgba(22,163,74,.35)":v==="inprogress"?"rgba(217,119,6,.35)":v==="new"?"rgba(41,53,93,.2)":"rgba(41,53,93,.25)"),
              background:cerStatusFilter===v?(v==="completed"?"rgba(22,163,74,.1)":v==="inprogress"?"rgba(217,119,6,.1)":v==="new"?"rgba(41,53,93,.08)":"#29355D"):"#fff",
              color:cerStatusFilter===v?(v==="completed"?"#15803d":v==="inprogress"?"#b45309":v==="new"?"#29355D":"#fff"):(v==="completed"?"#15803d":v==="inprogress"?"#b45309":"#808080")}}>
            {l}
          </button>
        ))}
      </div>

      {/* Table */}
      {csmRows.length===0 ? (
        <div style={{...S.card,textAlign:"center",padding:"40px 24px",color:"#808080"}}>
          <div style={{fontSize:28,marginBottom:10}}>📋</div>
          <div style={{fontSize:14,fontWeight:600,color:"#29355D",marginBottom:6}}>No CER data for this period</div>
          <div style={{fontSize:12}}>Try a different date range or check that the Google Sheet is published</div>
        </div>
      ) : (
        <div style={{background:"#fff",border:"0.5px solid rgba(41,53,93,.1)",borderRadius:12,overflow:"hidden",boxShadow:"0 1px 4px rgba(41,53,93,.05)"}}>
          <table style={{width:"100%",borderCollapse:"collapse",fontSize:12}}>
            <thead>
              <tr>
                <th style={{...S.th,width:28}}></th>
                <th style={S.th} onClick={()=>sortCol("csm")}>CSM <span style={{fontSize:9,opacity:.6}}>{sortIcon("csm")}</span></th>
                <th style={{...S.th,textAlign:"right"}} onClick={()=>sortCol("assigned")}>Assigned <span style={{fontSize:9,opacity:.6}}>{sortIcon("assigned")}</span></th>
                <th style={{...S.th,textAlign:"right"}} onClick={()=>sortCol("completed")}>Completed <span style={{fontSize:9,opacity:.6}}>{sortIcon("completed")}</span></th>
                <th style={{...S.th,textAlign:"right"}} onClick={()=>sortCol("inprogress")}>In progress <span style={{fontSize:9,opacity:.6}}>{sortIcon("inprogress")}</span></th>
                <th style={{...S.th,textAlign:"right"}} onClick={()=>sortCol("new")}>New <span style={{fontSize:9,opacity:.6}}>{sortIcon("new")}</span></th>
              </tr>
            </thead>
            <tbody>
              {csmRows.map(g => {
                const isExp = cerExpanded===g.name;
                const acctRows = sortAccts(g.rows);
                return (
                  <React.Fragment key={g.name}>
                    <tr onClick={()=>setCerExpanded(isExp?null:g.name)}
                      style={{cursor:"pointer",background:isExp?"rgba(41,53,93,.03)":"#fff",transition:"background .1s"}}>
                      <td style={{...S.td,color:"#808080",fontSize:13,paddingLeft:14}}>{isExp?"▼":"▶"}</td>
                      <td style={{...S.td,fontWeight:600,color:"#29355D"}}>{dispName(g.name)}</td>
                      <td style={{...S.td,textAlign:"right"}}>{g.assigned}</td>
                      <td style={{...S.td,textAlign:"right",color:"#16a34a",fontWeight:g.completed>0?600:400}}>{g.completed||"—"}</td>
                      <td style={{...S.td,textAlign:"right",color:g.inprogress>0?"#d97706":"#ccc"}}>{g.inprogress||"—"}</td>
                      <td style={{...S.td,textAlign:"right",color:"#808080"}}>{g.newCount||"—"}</td>
                    </tr>
                    {isExp&&(
                      <tr>
                        <td colSpan={6} style={{padding:0,background:"rgba(41,53,93,.02)"}}>
                          <table style={{width:"100%",borderCollapse:"collapse",fontSize:13}}>
                            <thead>
                              <tr style={{borderBottom:"0.5px solid rgba(41,53,93,.08)"}}>
                                <th style={{...S.th,paddingLeft:44,fontSize:9}} onClick={()=>sortAcct("acct")}>Account <span style={{fontSize:8,opacity:.6}}>{sortAcctIcon("acct")}</span></th>
                                <th style={{...S.th,fontSize:9}} onClick={()=>sortAcct("date")}>Form start date <span style={{fontSize:8,opacity:.6}}>{sortAcctIcon("date")}</span></th>
                                <th style={{...S.th,fontSize:9}} onClick={()=>sortAcct("status")}>Status <span style={{fontSize:8,opacity:.6}}>{sortAcctIcon("status")}</span></th>
                              </tr>
                            </thead>
                            <tbody>
                              {acctRows.map((r,i)=>(
                                <tr key={i} style={{borderBottom:"0.5px solid rgba(41,53,93,.04)"}}>
                                  <td style={{padding:"7px 12px 7px 44px",color:"#29355D"}}>{r["Account"]||"—"}</td>
                                  <td style={{padding:"7px 12px",color:"#808080"}}>{fmtDate(r["Form Start Date"])}</td>
                                  <td style={{padding:"7px 12px"}}>{statusPill(getStatus(r))}</td>
                                </tr>
                              ))}
                            </tbody>
                          </table>
                        </td>
                      </tr>
                    )}
                  </React.Fragment>
                );
              })}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}
// ═══════════════════════════════════════════════════════════════════════════


// ═══════════════════════════════════════════════════════════════════════════
// CAPACITY VIEW — master PIN only, hidden from coaches and CSMs
// ═══════════════════════════════════════════════════════════════════════════
function CapacityView({csms=[], callData={}, callRaw=[], cadenceFull=[], domoBoq=[], filterCoach="", filterCSM=""}) {
  const [capPeriod, setCapPeriod] = React.useState("today"); // today | week | month | quarter

  const now = new Date();
  const startOfDay = d => { const x = new Date(d); x.setHours(0,0,0,0); return x; };
  const todayStart = startOfDay(now);

  // ── Real period boundaries (local time) ──────────────────────────────────
  const dow = todayStart.getDay(); // 0=Sun..6=Sat
  const mondayOffset = dow===0 ? 6 : dow-1;
  const weekStart = new Date(todayStart); weekStart.setDate(weekStart.getDate()-mondayOffset);
  const monthStart = new Date(now.getFullYear(), now.getMonth(), 1);
  const qStartMonth = Math.floor(now.getMonth()/3)*3;
  const quarterStart = new Date(now.getFullYear(), qStartMonth, 1);

  const PERIODS = {
    today:   {label:"Today",           start: todayStart},
    week:    {label:"This week (WTD)", start: weekStart},
    month:   {label:"Month to date",   start: monthStart},
    quarter: {label:"Quarter to date", start: quarterStart},
  };
  const period = PERIODS[capPeriod];

  // Working days elapsed in the period so far (Mon–Fri, inclusive of today) —
  // this is what "average per day" divides by, so it's a real trailing average,
  // not a forward-looking projection.
  const workDaysElapsed = (start) => {
    let n = 0;
    const d = new Date(start);
    while (d <= todayStart) {
      const wd = d.getDay();
      if (wd!==0 && wd!==6) n++;
      d.setDate(d.getDate()+1);
    }
    return Math.max(1, n);
  };
  const elapsedDays = workDaysElapsed(period.start);

  // Daily targets — always expressed per working day, regardless of which
  // period is selected, so "avg/day" is apples-to-apples across Today/WTD/MTD/QTD.
  const dailyCallTarget = [3,4];
  const dailyCadTarget  = [4,6];
  const dailyCombTarget = [7,10];

  const parseDate = s => { const d = new Date(s); return isNaN(d) ? null : d; };
  const inPeriod  = (date, start) => date >= start && date <= now;

  // ── BoB accounts per CSM (unchanged — from domoBoq) ───────────────────────
  const lfSwap = n => { if(!n)return n; const p=n.split(","); return p.length===2?p[1].trim()+" "+p[0].trim():n; };
  const bobByCsm = {}; // normName -> Set of EIDs
  domoBoq.forEach(r => {
    const csmRaw = String(r["CSM Name"]||"").trim();
    if (!csmRaw || /TOTAL|GRAND/i.test(csmRaw) || /\bTOTAL$/i.test(csmRaw)) return;
    const eid  = String(r["Enterprise ID"]||r["Enterprise Id"]||"").trim().toUpperCase();
    if (!eid || /count/i.test(eid)) return;
    const csmNorm = norm(lfSwap(csmRaw)) || lfSwap(csmRaw);
    if (!bobByCsm[csmNorm]) bobByCsm[csmNorm] = new Set();
    bobByCsm[csmNorm].add(eid);
  });

  // ── Cadence: true active-cadence accounts + a dated activity log ─────────
  // openAcctByCsm   = unique accounts per CSM with >=1 Open touchpoint (the
  //                   real "active cadence" count — no BoB name-matching).
  // cadActivityByCsm = dated log of Completed/Open touchpoints (work actually
  //                    completed or currently assigned), used for period averages.
  const openAcctByCsm = {};
  const cadActivityByCsm = {};
  cadenceFull.forEach(r => {
    const assigned = String(r["Cadence Member: Assigned"]||"").trim();
    const acct     = String(r["Cadence Member: Account"]||"").trim();
    const status   = String(r["Status"]||"").trim();
    if (!assigned || !acct) return;
    const csmNorm = norm(assigned) || assigned;
    if (!openAcctByCsm[csmNorm]) { openAcctByCsm[csmNorm] = new Set(); cadActivityByCsm[csmNorm] = []; }
    const acctKey = acct.toLowerCase().trim();
    if (status === "Open") openAcctByCsm[csmNorm].add(acctKey);
    // "Work completed or assigned" = Completed (done) or Open (currently due) —
    // Skipped/Removed rows are neither, so they're excluded from the activity log.
    if (status === "Completed" || status === "Open") {
      const due = parseDate(r["Due Date/Time"]);
      if (due) cadActivityByCsm[csmNorm].push({date: due});
    }
  });

  // ── Onboarding: unique client accounts per CSM per month, by email ────────
  // This pass is intentionally separate from call-volume counting below — it
  // NEEDS an email to identify a distinct client, so rows without one are
  // correctly excluded here (they simply can't be attributed to an account).
  const callAcctsByCsm = {}; // normName -> {monthKey (YYYY-MM) -> Set of client emails that month}
  const seenBooking = new Set(); // same booking re-uploaded (Scheduled -> Completed) shouldn't double count
  callRaw.forEach(r => {
    const apptTime = String(r["Appointment Time"] || r["appointment_time"] || "").trim();
    const staffRaw = String(r["Staff Name"] || r["Staff"] || r["csm_name"] || r["Assigned To"] || "").trim();
    const svcRaw   = String(r["Service Name"] || r["Service"] || r["service_type"] || r["Appointment Type"] || "").trim();
    const emailRaw = String(r["Client Email"] || r["email"] || "").trim().toLowerCase();
    if (!staffRaw || !apptTime || !emailRaw) return;
    const csm = norm(staffRaw) || staffRaw;
    const apptStatus = String(r["Appointment Status"] || r["Status"] || r["status"] || "").toLowerCase().trim();
    let statusKey = null;
    if      (apptStatus.includes("complet"))                                                             statusKey = "completed";
    else if (apptStatus.includes("no show") || apptStatus.includes("noshow") || apptStatus.includes("no-show")) statusKey = "no show";
    else if (apptStatus.includes("cancel"))                                                              statusKey = "cancelled";
    else if (apptStatus.includes("schedul") || apptStatus.includes("created"))                          statusKey = "scheduled";
    if (!statusKey || statusKey === "cancelled") return; // a cancelled call didn't work the account

    const dedupKey = [apptTime, emailRaw, svcRaw].join("|");
    if (seenBooking.has(dedupKey)) return;
    seenBooking.add(dedupKey);

    const apptDate = parseDate(apptTime);
    if (!apptDate) return;
    const monthKey = apptDate.getFullYear() + "-" + String(apptDate.getMonth()+1).padStart(2,"0");

    if (!callAcctsByCsm[csm]) callAcctsByCsm[csm] = {};
    if (!callAcctsByCsm[csm][monthKey]) callAcctsByCsm[csm][monthKey] = new Set();
    callAcctsByCsm[csm][monthKey].add(emailRaw);
  });

  // ── Call volume per day, per CSM — built from `callData`, the SAME
  //    already-deduped aggregation the Calls page itself displays (handles
  //    pre-aggregated legacy rows and doesn't require an email on every row,
  //    unlike the email-keyed onboarding pass above). This is what "calls
  //    today / this week / etc." should match against the Calls tab. ──────
  const callVolByCsmDay = {}; // normName -> {dayKey -> count}  (completed+scheduled+noShow, excludes cancelled)
  Object.entries(callData).forEach(([csm, days]) => {
    callVolByCsmDay[csm] = {};
    Object.entries(days).forEach(([dayKey, svcs]) => {
      let n = 0;
      Object.values(svcs).forEach(s => { n += (s.completed||0) + (s.scheduled||0) + (s.noShow||0); });
      callVolByCsmDay[csm][dayKey] = n;
    });
  });

  // ── Resolve a canonical (roster) name to whichever key a data source used ──
  const resolveKey = (canonicalNorm, map) => {
    if (map[canonicalNorm]) return canonicalNorm;
    const canonical = Object.values(NAME_NORM).find(v => norm(v) === canonicalNorm);
    if (canonical) {
      const aliasKey = Object.keys(NAME_NORM).find(k => NAME_NORM[k] === canonical && map[k]);
      if (aliasKey) return aliasKey;
    }
    return canonicalNorm;
  };

  // ── Per-CSM stats ─────────────────────────────────────────────────────────
  const csmRows = csms.map(c => {
    const csmNorm = norm(c.name);

    const bobKey = resolveKey(csmNorm, bobByCsm);
    const totalAccts = (bobByCsm[bobKey] || new Set()).size;

    const cadKey = resolveKey(csmNorm, openAcctByCsm);
    const activeCount = (openAcctByCsm[cadKey] || new Set()).size; // true active-cadence count

    const callKey = resolveKey(csmNorm, callVolByCsmDay);

    // Onboarding = AVERAGE unique clients called per month, by email — not a
    // lifetime cumulative count. A cumulative count picks up years of call
    // history (former clients, reassigned accounts, one-off outreach) and
    // balloons far past the current book size. Averaging per calendar month
    // gives a steady-state "how many distinct clients does this CSM typically
    // call in a month" figure instead.
    const onbKey = resolveKey(csmNorm, callAcctsByCsm);
    const monthlyClientSets = Object.values(callAcctsByCsm[onbKey] || {});
    const onboardingCount = monthlyClientSets.length
      ? monthlyClientSets.reduce((s,set)=>s+set.size,0) / monthlyClientSets.length
      : 0;
    const onboardingMonths = monthlyClientSets.length;

    // "Actively working" = cadence accounts + call accounts. This is a simple
    // sum, not a de-duplicated union — cadence is keyed by company name and
    // calls by client email, and there's no shared key today to reconcile
    // overlap between the two sources. Cross-referenced against total book size.
    const workingCount = activeCount + onboardingCount;
    const workingPct = totalAccts > 0 ? workingCount / totalAccts : null;

    // ── Real, period-based averages (not a forward projection) ─────────────
    const cadInPeriod  = (cadActivityByCsm[cadKey] || []).filter(a => inPeriod(a.date, period.start)).length;
    const callInPeriod = Object.entries(callVolByCsmDay[callKey] || {})
      .filter(([dayKey]) => {
        const [y,m,d] = dayKey.split("-").map(Number);
        return inPeriod(new Date(y, m-1, d), period.start); // local-time construction — a bare "YYYY-MM-DD" string parses as UTC and can land on the wrong local day
      })
      .reduce((s,[,n]) => s+n, 0);
    const callsPerDay = callInPeriod / elapsedDays;
    const cadPerDay   = cadInPeriod  / elapsedDays;
    const combined    = callsPerDay + cadPerDay;

    const getStatus = (val, [lo,hi]) => val>=lo&&val<=hi?"on":val<lo?"under":"over";

    return {
      c, name: c.name, totalAccts, activeCount, onboardingCount, onboardingMonths, workingCount, workingPct,
      cadInPeriod, callInPeriod, callsPerDay, cadPerDay, combined,
      callStatus:    getStatus(callsPerDay, dailyCallTarget),
      cadStatus:     getStatus(cadPerDay,   dailyCadTarget),
      overallStatus: getStatus(combined,    dailyCombTarget),
    };
  }).filter(r => r.totalAccts > 0 || r.activeCount > 0 || r.onboardingCount > 0 || r.callInPeriod > 0)
    .sort((a,b) => b.totalAccts - a.totalAccts);

  // ── Org totals ─────────────────────────────────────────────────────────────
  const orgAccts    = csmRows.reduce((s,r)=>s+r.totalAccts,0);
  const orgActive   = csmRows.reduce((s,r)=>s+r.activeCount,0);
  const orgOnb      = csmRows.reduce((s,r)=>s+r.onboardingCount,0);
  const orgWorking  = csmRows.reduce((s,r)=>s+r.workingCount,0);
  const avgCalls    = csmRows.length ? csmRows.reduce((s,r)=>s+r.callsPerDay,0)/csmRows.length : 0;
  const avgCad      = csmRows.length ? csmRows.reduce((s,r)=>s+r.cadPerDay,0)/csmRows.length : 0;

  const statusPill = s => {
    const col = s==="on"?"#16a34a":s==="under"?"#d97706":"#dc2626";
    const bg  = s==="on"?"rgba(22,163,74,.1)":s==="under"?"rgba(217,119,6,.1)":"rgba(220,38,38,.1)";
    const lbl = s==="on"?"On track":s==="under"?"Under":"Over";
    return <span style={{fontSize:11,fontWeight:600,padding:"2px 8px",borderRadius:20,background:bg,color:col}}>{lbl}</span>;
  };

  const S = {
    card:{background:"#fff",borderRadius:12,padding:"18px 22px",boxShadow:"0 1px 4px rgba(41,53,93,.07)",marginBottom:14},
    tile:{background:"rgba(41,53,93,.04)",borderRadius:8,padding:"12px 14px"},
    th:{padding:"8px 10px",fontSize:11,textTransform:"uppercase",color:"#808080",fontWeight:500,letterSpacing:"0.04em",borderBottom:"0.5px solid rgba(41,53,93,.08)",whiteSpace:"nowrap"},
    td:{padding:"8px 10px",borderBottom:"0.5px solid rgba(41,53,93,.05)",color:"#29355D",verticalAlign:"middle"},
  };

  const fmt1 = n => Number(n||0).toFixed(1);

  return (
    <div style={{maxWidth:1200,margin:"0 auto"}}>
      {/* Header */}
      <div style={{display:"flex",alignItems:"flex-start",justifyContent:"space-between",marginBottom:16,flexWrap:"wrap",gap:8}}>
        <div>
          <div style={{fontSize:20,fontWeight:700,color:"#29355D",marginBottom:2}}>⚡ Capacity Model</div>
          <div style={{fontSize:13,color:"#808080"}}>Master view only · {period.label} · {elapsedDays} working day{elapsedDays===1?"":"s"} elapsed</div>
        </div>
        <div style={{display:"flex",gap:6}}>
          {[["today","Today"],["week","Week"],["month","MTD"],["quarter","QTD"]].map(([v,l])=>(
            <button key={v} onClick={()=>setCapPeriod(v)}
              style={{padding:"4px 14px",borderRadius:20,fontSize:13,fontWeight:500,cursor:"pointer",
                border:"0.5px solid "+(capPeriod===v?"#29355D":"rgba(41,53,93,.2)"),
                background:capPeriod===v?"#29355D":"#fff",color:capPeriod===v?"#fff":"#808080"}}>
              {l}
            </button>
          ))}
        </div>
      </div>

      {/* Targets — always per working day, so they're comparable across periods */}
      <div style={{display:"flex",gap:6,alignItems:"center",marginBottom:14,flexWrap:"wrap"}}>
        <span style={{fontSize:12,color:"#808080"}}>Targets (per working day):</span>
        {[["📞 Calls",dailyCallTarget],["✅ Cadence",dailyCadTarget],["Combined",dailyCombTarget]].map(([lbl,[lo,hi]])=>(
          <span key={lbl} style={{fontSize:12,padding:"2px 10px",borderRadius:20,background:"rgba(41,53,93,.05)",color:"#808080",border:"0.5px solid rgba(41,53,93,.1)"}}>
            {lbl}: {lo}–{hi}
          </span>
        ))}
      </div>

      {/* Org summary tiles */}
      <div style={{display:"grid",gridTemplateColumns:"repeat(6,minmax(0,1fr))",gap:10,marginBottom:14}}>
        {[
          {l:"Total accounts (BoB)",  v:orgAccts,  sub:`${csmRows.length} CSMs · ${(orgAccts/Math.max(csmRows.length,1)).toFixed(1)} avg`, col:"#29355D"},
          {l:"In cadence (active)",   v:orgActive, sub:`${orgAccts>0?Math.round(orgActive/orgAccts*100):0}% of book`, col:"#16a34a"},
          {l:"Onboarding (calls, avg/mo)", v:orgOnb.toFixed(1), sub:"avg unique clients/month, by email", col:"#2a78d6"},
          {l:"Actively working",      v:orgWorking.toFixed(1),sub:`cadence + calls avg · ${orgAccts>0?Math.round(orgWorking/orgAccts*100):0}% of book`, col:"#7c3aed"},
          {l:`Avg calls / day (${period.label})`,  v:fmt1(avgCalls), sub:`target ${dailyCallTarget[0]}–${dailyCallTarget[1]}`, col:"#29355D"},
          {l:`Avg cadence / day (${period.label})`,v:fmt1(avgCad),   sub:`target ${dailyCadTarget[0]}–${dailyCadTarget[1]}`, col:"#29355D"},
        ].map(t=>(
          <div key={t.l} style={S.tile}>
            <div style={{fontSize:12,color:"#808080",marginBottom:4}}>{t.l}</div>
            <div style={{fontSize:22,fontWeight:700,color:t.col,lineHeight:1,marginBottom:3}}>{t.v}</div>
            <div style={{fontSize:11,color:"#aaa"}}>{t.sub}</div>
          </div>
        ))}
      </div>

      {/* Per-CSM table */}
      <div style={S.card}>
        <div style={{fontSize:13,fontWeight:600,color:"#29355D",marginBottom:14}}>Per-CSM workload breakdown</div>
        <div style={{overflowX:"auto"}}>
          <table style={{width:"100%",borderCollapse:"collapse",fontSize:12,minWidth:900}}>
            <thead>
              <tr>
                <th style={{...S.th,textAlign:"left"}}>CSM</th>
                <th style={{...S.th,textAlign:"right"}}>BoB Accts</th>
                <th style={{...S.th,textAlign:"right",color:"#16a34a"}}>✅ Active (cadence)</th>
                <th style={{...S.th,textAlign:"right",color:"#2a78d6"}}>📞 Onboarding (avg/mo)</th>
                <th style={{...S.th,textAlign:"right",color:"#7c3aed"}}>🔥 Actively working</th>
                <th style={{...S.th,textAlign:"right"}}>Calls/day</th>
                <th style={{...S.th,textAlign:"center"}}>Call status</th>
                <th style={{...S.th,textAlign:"right"}}>Cad/day</th>
                <th style={{...S.th,textAlign:"center"}}>Cad status</th>
                <th style={{...S.th,textAlign:"right"}}>Combined</th>
                <th style={{...S.th,textAlign:"center"}}>Overall</th>
              </tr>
            </thead>
            <tbody>
              {csmRows.map(r => {
                const actPct = r.totalAccts>0 ? r.activeCount/r.totalAccts : null;
                const wrkPct = r.workingPct;
                return (
                  <tr key={r.name} style={{background:"#fff"}}>
                    <td style={{...S.td,fontWeight:600,textAlign:"left"}}>{dispName(r.name)}</td>
                    <td style={{...S.td,textAlign:"right",color:"#808080"}}>{r.totalAccts}</td>
                    <td style={{...S.td,textAlign:"right",color:"#16a34a",fontWeight:600}}>
                      {r.activeCount} {actPct!=null && <span style={{fontSize:11,color:"#aaa",fontWeight:400}}>({Math.round(actPct*100)}%)</span>}
                    </td>
                    <td style={{...S.td,textAlign:"right",color:"#2a78d6",fontWeight:600}}>
                      {fmt1(r.onboardingCount)}
                      <div style={{fontSize:10,color:"#aaa"}}>avg/mo · {r.onboardingMonths} mo data</div>
                    </td>
                    <td style={{...S.td,textAlign:"right",color:"#7c3aed",fontWeight:600}}>
                      {fmt1(r.workingCount)} {wrkPct!=null && <span style={{fontSize:11,color:"#aaa",fontWeight:400}}>({Math.round(wrkPct*100)}%)</span>}
                    </td>
                    <td style={{...S.td,textAlign:"right",fontWeight:600}}>
                      {fmt1(r.callsPerDay)}
                      <div style={{fontSize:10,color:"#aaa"}}>{r.callInPeriod} in period</div>
                    </td>
                    <td style={{...S.td,textAlign:"center"}}>{statusPill(r.callStatus)}</td>
                    <td style={{...S.td,textAlign:"right",fontWeight:600}}>
                      {fmt1(r.cadPerDay)}
                      <div style={{fontSize:10,color:"#aaa"}}>{r.cadInPeriod} in period</div>
                    </td>
                    <td style={{...S.td,textAlign:"center"}}>{statusPill(r.cadStatus)}</td>
                    <td style={{...S.td,textAlign:"right",fontWeight:600}}>{fmt1(r.combined)}</td>
                    <td style={{...S.td,textAlign:"center"}}>{statusPill(r.overallStatus)}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
        <div style={{fontSize:11,color:"#aaa",marginTop:10,paddingTop:10,borderTop:"0.5px solid rgba(41,53,93,.06)"}}>
          Active = unique accounts w/ an open cadence touchpoint (no BoB name-matching) · Onboarding = average unique clients called per calendar month, deduped by email (a lifetime cumulative count would include years of former/reassigned clients and balloon past book size) · Actively working = Active + Onboarding avg (simple sum — the two sources use different identifiers, so this can double-count an account that's in both cadence and calls) · Calls/Cad per day = real activity in the selected period ÷ {elapsedDays} working day{elapsedDays===1?"":"s"} elapsed so far, not a projection.
        </div>
      </div>
    </div>
  );
}

