// Parses the live "FIs Needing Action" sheet export into the same row shape
// FulfillmentView and the My Dashboard card already work with. Column headers
// match fis.xlsx exactly (verified against a fresh live pull on 2026-08-21).
function mapFI(rows) {
  if (!rows || rows.length === 0) return [];
  return rows.map(r => {
    const fiOwner = String(r["Fulfillment Item: Owner Name"]||"").trim();
    const account = String(r["Account"]||"").trim();
    if (!fiOwner || !account) return null;
    const udac = String(r["UDAC"]||"").toUpperCase();
    const fiType = udac.includes("SOC") ? "Social FI"
                 : (udac.includes("WEB") || udac.includes("SITE")) ? "Website FI"
                 : "Other";
    const aging = parseFloat(String(r["Function Aging (Days)"]||"0").replace(/[^0-9.\-]/g,"")) || 0;
    return {
      fiType,
      coach: String(r["Onboarding Form: CSM Coach Name"]||"").trim(),
      fiOwner,
      ofOwner: String(r["Onboarding Form Owner"]||"").trim(),
      account,
      func: String(r["Current Function"]||"").trim(),
      aging,
      fiNum: String(r["Fulfillment Item: Fulfillment Item ID"]||"").trim(),
      ofNum: String(r["Onboarding Form: Onboarding Form ID"]||"").trim(),
    };
  }).filter(Boolean);
}

// ── Live Q3 SF-based BoB join ────────────────────────────────────────────
// Mirrors the exact methodology from q3_BoB_8-25.xlsx's "SF retention detail"
// / "BoB Retention" tabs:
//   - BOQ = sum of per-L2-line "End of Quarter" values for that EID, from the
//     Q3 BoQ export (CSM always comes from this side when the EID exists here).
//   - Current = "SaaS Revenue" for that EID from the Current SaaS Revenue
//     export (a fresh Salesforce pull, account-level).
//   - An EID with no BOQ record ("Added") counts its current value as its own
//     BOQ — 100% retained by definition — rather than showing as an
//     undefined/infinite increase.
//   - An EID with no current record ("Lost") keeps its BOQ with current = 0.
// CAUTION: "SaaS Revenue" on the Current side is in LOCAL CURRENCY
// (USD/AUD/NZD) and is NOT FX-converted — several CSMs (Dave Crisler, Sylvia
// Appla, Warda Gul, Matt Daly, Tracy-Ann Gaudencio, etc.) have AU/NZ books, so
// summed dollar totals blend currencies as if they were equivalent. This
// matches the source workbook's own known limitation — it isn't something
// introduced here — but it means any BOQ/Current $ total that spans those
// CSMs is not a true apples-to-apples USD figure.
function buildSFBobRows(boqRows, curRows) {
  if ((!boqRows || boqRows.length===0) && (!curRows || curRows.length===0)) return [];

  const pf = v => {
    let s = String(v||"0").trim();
    const neg = s.startsWith("(") && s.endsWith(")");
    s = s.replace(/[^0-9.\-]/g,"");
    const x = parseFloat(s);
    return isNaN(x) ? 0 : (neg ? -Math.abs(x) : x);
  };

  // BOQ side — sum per EID across L2 lines, capture CSM name (raw "Last, First")
  const boqByEid = {}; // eid -> {csm, boq}
  (boqRows||[]).forEach(r => {
    const eid = String(r["Enterprise ID"]||"").trim().toUpperCase();
    if (!eid) return;
    const csm = String(r["CSM Name"]||"").trim();
    const val = pf(r["End of Quarter"]);
    if (!boqByEid[eid]) boqByEid[eid] = {csm, boq: 0, acct: String(r["Account Name"]||"").trim()};
    boqByEid[eid].boq += val;
    if (!boqByEid[eid].csm && csm) boqByEid[eid].csm = csm;
  });

  // Current side — one row per account already
  const curByEid = {}; // eid -> {csm, cur, acct}
  (curRows||[]).forEach(r => {
    const eid = String(r["Enterprise Id"]||r["Enterprise ID"]||"").trim().toUpperCase();
    if (!eid) return;
    curByEid[eid] = {
      csm: String(r["Client Success Manager"]||"").trim(),
      cur: pf(r["SaaS Revenue"]),
      acct: String(r["Account Name"]||"").trim(),
    };
  });

  const allEids = new Set([...Object.keys(boqByEid), ...Object.keys(curByEid)]);
  const rows = [];
  allEids.forEach(eid => {
    const b = boqByEid[eid];
    const c = curByEid[eid];
    const cur = c ? c.cur : 0;
    const boqRaw = b ? b.boq : 0;
    const isAdded = !b; // no BOQ record at all for this EID
    const boq = isAdded ? cur : boqRaw; // Added accounts: BOQ = current, 100% retained
    const csm = (b && b.csm) || (c && c.csm) || "";
    const acct = (b && b.acct) || (c && c.acct) || "";
    let status;
    if (isAdded) status = "Added";
    else if (!c || cur===0) status = "Lost";
    else if (cur > boq) status = "Increase";
    else if (cur < boq) status = "Decrease";
    else status = "No Change";
    if (!csm) return; // can't attribute to anyone — drop rather than show blank
    rows.push([csm, eid, acct, Math.round(boq*100)/100, Math.round(cur*100)/100, status]);
  });
  return rows;
}

// Normalizes a CSM name from either SF BoB source to the canonical roster
// name: handles "Last, First" (from the BoQ side) as well as plain "First
// Last" (already the format the Current Revenue side uses).
function normalizeSFCsmName(raw) {
  const s = String(raw||"").trim();
  if (!s) return "";
  if (s.includes(",")) {
    const [last, first] = s.split(",", 2);
    const swapped = (first.trim()+" "+last.trim()).replace(/  +/g," ").trim();
    return norm(swapped) || swapped;
  }
  return norm(s) || s;
}

// Rolls the live/pre-build SF BoB row list up to one summary object per CSM —
// this is the single source every dashboard surface (Leaderboard, Coaching,
// Digest, My Dashboard, AI Coach) should read Q3 retention/net-change from,
// so they can't silently drift out of sync with each other or with the Book
// of Business tab itself.
function summarizeSFBobByCsm(sfBobRows) {
  const byCsm = {};
  (sfBobRows||[]).forEach(([csmRaw, eid, acct, boq, cur, status]) => {
    const csm = normalizeSFCsmName(csmRaw);
    if (!csm) return;
    if (!byCsm[csm]) byCsm[csm] = {boq:0, cur:0, accts:0, increaseCount:0, decreaseCount:0, cancelledCount:0, addedCount:0};
    const g = byCsm[csm];
    g.boq += boq; g.cur += cur; g.accts++;
    if (status==="Increase")  g.increaseCount++;
    if (status==="Decrease")  g.decreaseCount++;
    if (status==="Lost")      g.cancelledCount++;
    if (status==="Added")     g.addedCount++;
  });
  Object.values(byCsm).forEach(g => {
    g.net = g.cur - g.boq;
    g.ret = g.boq > 0 ? g.cur/g.boq : null;
  });
  return byCsm;
}



// An FI is flagged urgent if it's been sitting in its Current Function longer
// than its threshold — OR if it's in a function that's ALWAYS urgent
// regardless of aging (Unengaged: an unengaged client is a fire the moment
// it's noticed, not after N days).
// "Launch" doesn't appear anywhere in the current data, but the threshold is
// wired in now so it's ready the moment that function shows up.
const FI_SLA_DAYS = { "Consultation": 5, "Review": 2, "Launch": 1, "Voice of the Client": 2 };
const FI_ALWAYS_URGENT_FUNCTIONS = new Set(["Unengaged"]);
function fiIsUrgent(r) {
  if (FI_ALWAYS_URGENT_FUNCTIONS.has(r.func)) return true;
  const threshold = FI_SLA_DAYS[r.func];
  return threshold != null && r.aging > threshold;
}

function FulfillmentView({filterCoach="", filterCSM="", rows}) {
  const isLive = !!(rows && rows.length>0);
  const dataRows = isLive ? rows : FI_RAW;
  const [sortCol, setSortCol] = React.useState("fiOwner");
  const [sortDir, setSortDir] = React.useState("asc");
  const [typeFilter, setTypeFilter] = React.useState(""); // "" | "Social FI" | "Website FI"
  const [funcFilter, setFuncFilter] = React.useState(""); // "" | a Current Function value, scoped to typeFilter
  const [urgentOnly, setUrgentOnly] = React.useState(false);

  const onSelectType = v => { setTypeFilter(v); setFuncFilter(""); }; // changing type invalidates any function picked under the old type

  const unmappedCoaches = [...new Set(dataRows.map(r=>r.coach))].filter(c=>!FI_COACH_EMAIL_MAP[c]);

  // Functions available within whatever type is currently selected (or all
  // types, if "All" is active) — this is what populates the function dropdown.
  const availableFunctions = [...new Set(
    dataRows.filter(r => !typeFilter || r.fiType===typeFilter).map(r=>r.func)
  )].sort();

  const scoped = dataRows.filter(r => {
    const coachEmail = FI_COACH_EMAIL_MAP[r.coach] || null;
    if (filterCoach && coachEmail !== filterCoach) return false;
    if (filterCSM && r.fiOwner !== filterCSM && r.ofOwner !== filterCSM) return false;
    if (typeFilter && r.fiType !== typeFilter) return false;
    if (funcFilter && r.func !== funcFilter) return false;
    if (urgentOnly && !fiIsUrgent(r)) return false;
    return true;
  });

  const urgentItems = [...scoped].filter(fiIsUrgent).sort((a,b)=>{
    // Always-urgent functions (Unengaged) first, then worst-aging first
    const aAlways = FI_ALWAYS_URGENT_FUNCTIONS.has(a.func), bAlways = FI_ALWAYS_URGENT_FUNCTIONS.has(b.func);
    if (aAlways !== bAlways) return aAlways ? -1 : 1;
    return b.aging - a.aging;
  });

  const onSort = col => { if (sortCol===col) setSortDir(d=>d==="asc"?"desc":"asc"); else { setSortCol(col); setSortDir("asc"); } };

  const sorted = [...scoped].sort((a,b) => {
    const av = a[sortCol], bv = b[sortCol];
    let cmp;
    if (typeof av === "number") cmp = av - bv;
    else cmp = String(av||"").toLowerCase().localeCompare(String(bv||"").toLowerCase());
    if (cmp === 0 && sortCol === "fiOwner") cmp = String(a.ofOwner||"").toLowerCase().localeCompare(String(b.ofOwner||"").toLowerCase());
    return sortDir==="asc" ? cmp : -cmp;
  });

  const total = scoped.length;
  const social = scoped.filter(r=>r.fiType==="Social FI").length;
  const website = scoped.filter(r=>r.fiType==="Website FI").length;
  const avgAging = total ? (scoped.reduce((s,r)=>s+r.aging,0)/total) : 0;

  const S = {
    card:{background:"#fff",borderRadius:12,padding:"18px 22px",boxShadow:"0 1px 4px rgba(41,53,93,.07)",marginBottom:14},
    tile:{background:"rgba(41,53,93,.04)",borderRadius:8,padding:"12px 14px"},
    th:{padding:"8px 10px",fontSize:11,textTransform:"uppercase",color:"#808080",fontWeight:500,letterSpacing:"0.04em",borderBottom:"0.5px solid rgba(41,53,93,.08)",whiteSpace:"nowrap",cursor:"pointer",userSelect:"none"},
    td:{padding:"8px 10px",borderBottom:"0.5px solid rgba(41,53,93,.05)",color:"#29355D",verticalAlign:"middle"},
  };
  const sortArrow = col => sortCol===col ? (sortDir==="asc"?" ↑":" ↓") : "";
  const fmt1 = n => Number(n||0).toFixed(1);

  return (
    <div style={{maxWidth:1200,margin:"0 auto"}}>
      <div style={{fontSize:20,fontWeight:700,color:"#29355D",marginBottom:4}}>📋 Fulfillment Items</div>
      <div style={{fontSize:13,color:"#808080",marginBottom:14}}>{isLive ? "Live — refreshes automatically from the \"FIs Needing Action\" sheet" : "Static snapshot, transcribed 2026-08-21 — CSV_FI isn't returning data yet, showing the fallback snapshot"}</div>

      <div style={{display:"grid",gridTemplateColumns:"repeat(5,minmax(0,1fr))",gap:10,marginBottom:14}}>
        {[
          {l:"Total FIs",   v:total, sub:"in current scope", col:"#29355D"},
          {l:"🚨 Urgent",   v:urgentItems.length, sub:total?Math.round(urgentItems.length/total*100)+"% of scope":"—", col:"#dc2626"},
          {l:"Social FI",   v:social, sub:total?Math.round(social/total*100)+"% of total":"—", col:"#d97706"},
          {l:"Website FI",  v:website, sub:total?Math.round(website/total*100)+"% of total":"—", col:"#2a78d6"},
          {l:"Avg Function Aging", v:fmt1(avgAging)+"d", sub:"days in current function", col:"#7c3aed"},
        ].map(t=>(
          <div key={t.l} style={S.tile}>
            <div style={{fontSize:12,color:"#808080",marginBottom:4}}>{t.l}</div>
            <div style={{fontSize:22,fontWeight:700,color:t.col,lineHeight:1,marginBottom:3}}>{t.v}</div>
            <div style={{fontSize:11,color:"#aaa"}}>{t.sub}</div>
          </div>
        ))}
      </div>

      <div style={{display:"flex",gap:6,marginBottom:14,flexWrap:"wrap",alignItems:"center"}}>
        {[["","All"],["Social FI","Social FI"],["Website FI","Website FI"]].map(([v,l])=>(
          <button key={v} onClick={()=>onSelectType(v)}
            style={{padding:"4px 12px",borderRadius:20,fontSize:12,fontWeight:500,cursor:"pointer",
              border:"0.5px solid "+(typeFilter===v?"#29355D":"rgba(41,53,93,.2)"),
              background:typeFilter===v?"#29355D":"#fff",color:typeFilter===v?"#fff":"#808080"}}>
            {l}
          </button>
        ))}
        {typeFilter && (
          <select value={funcFilter} onChange={e=>setFuncFilter(e.target.value)}
            style={{padding:"4px 10px",borderRadius:20,fontSize:12,fontWeight:500,cursor:"pointer",
              border:"0.5px solid #29355D",background:"#fff",color:"#29355D"}}>
            <option value="">All functions ({typeFilter})</option>
            {availableFunctions.map(f => <option key={f} value={f}>{f}</option>)}
          </select>
        )}
        <button onClick={()=>setUrgentOnly(u=>!u)}
          style={{padding:"4px 12px",borderRadius:20,fontSize:12,fontWeight:600,cursor:"pointer",
            border:"0.5px solid "+(urgentOnly?"#dc2626":"rgba(220,38,38,.3)"),
            background:urgentOnly?"#dc2626":"#fff",color:urgentOnly?"#fff":"#dc2626"}}>
          🚨 Urgent only
        </button>
      </div>

      {urgentItems.length>0 && (
        <div style={{background:"rgba(220,38,38,.06)",border:"0.5px solid rgba(220,38,38,.35)",borderRadius:12,padding:"16px 20px",marginBottom:14}}>
          <div style={{fontSize:14,fontWeight:700,color:"#7f1d1d",marginBottom:4}}>🚨 Danger, Will Robinson — {urgentItems.length} Fulfillment Item{urgentItems.length===1?"":"s"} need attention</div>
          <div style={{fontSize:12,color:"#991b1b",marginBottom:12}}>
            Unengaged is always urgent · Consultation &gt; {FI_SLA_DAYS["Consultation"]}d · Review &gt; {FI_SLA_DAYS["Review"]}d · Voice of the Client &gt; {FI_SLA_DAYS["Voice of the Client"]}d · Launch &gt; {FI_SLA_DAYS["Launch"]}d
          </div>
          <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(260px,1fr))",gap:8}}>
            {urgentItems.slice(0,12).map(r=>(
              <div key={r.fiNum} style={{background:"#fff",borderRadius:8,padding:"8px 12px",borderLeft:"3px solid #dc2626"}}>
                <div style={{fontSize:12,fontWeight:600,color:"#29355D"}}>{r.account}</div>
                <div style={{fontSize:11,color:"#808080"}}>{r.fiOwner} · {r.func}</div>
                <div style={{fontSize:11,fontWeight:600,color:"#dc2626"}}>
                  {FI_ALWAYS_URGENT_FUNCTIONS.has(r.func) ? "Unengaged" : fmt1(r.aging)+"d in function"}
                </div>
              </div>
            ))}
          </div>
          {urgentItems.length>12 && <div style={{fontSize:11,color:"#991b1b",marginTop:8}}>+{urgentItems.length-12} more — check "🚨 Urgent only" below to see the full list.</div>}
        </div>
      )}

      <div style={S.card}>
        <div style={{fontSize:13,fontWeight:600,color:"#29355D",marginBottom:14}}>
          {typeFilter||funcFilter ? [typeFilter,funcFilter].filter(Boolean).join(" — ") : "All Fulfillment Items"} ({sorted.length}) — sorted by FI Owner, then Onboarding Form Owner
        </div>
        <div style={{overflowX:"auto"}}>
          <table style={{width:"100%",borderCollapse:"collapse",fontSize:12,minWidth:1000}}>
            <thead>
              <tr>
                <th style={S.th} onClick={()=>onSort("fiType")}>FI Type{sortArrow("fiType")}</th>
                <th style={S.th} onClick={()=>onSort("coach")}>Coach{sortArrow("coach")}</th>
                <th style={S.th} onClick={()=>onSort("fiOwner")}>FI Owner{sortArrow("fiOwner")}</th>
                <th style={S.th} onClick={()=>onSort("ofOwner")}>Onboarding Form Owner{sortArrow("ofOwner")}</th>
                <th style={S.th} onClick={()=>onSort("account")}>Account{sortArrow("account")}</th>
                <th style={S.th} onClick={()=>onSort("func")}>Current Function{sortArrow("func")}</th>
                <th style={{...S.th,textAlign:"right"}} onClick={()=>onSort("aging")}>Function Aging (Days){sortArrow("aging")}</th>
                <th style={S.th} onClick={()=>onSort("fiNum")}>FI Number{sortArrow("fiNum")}</th>
                <th style={S.th} onClick={()=>onSort("ofNum")}>Onboarding Form Number{sortArrow("ofNum")}</th>
              </tr>
            </thead>
            <tbody>
              {sorted.map((r,i) => {
                const urgent = fiIsUrgent(r);
                return (
                <tr key={r.fiNum+"-"+i} style={urgent?{background:"rgba(220,38,38,.05)"}:undefined}>
                  <td style={S.td}>
                    <span style={{fontSize:11,fontWeight:600,padding:"2px 8px",borderRadius:20,
                      background:r.fiType==="Social FI"?"rgba(217,119,6,.1)":"rgba(42,120,214,.1)",
                      color:r.fiType==="Social FI"?"#d97706":"#2a78d6"}}>{r.fiType}</span>
                  </td>
                  <td style={S.td}>{FI_COACH_EMAIL_MAP[r.coach] ? r.coach.replace(/([a-z])([A-Z])/g,"$1 $2").replace(/O'/,"O\u2019") : <span style={{color:"#d97706"}}>{r.coach} ⚠</span>}</td>
                  <td style={{...S.td,fontWeight:600}}>{r.fiOwner}</td>
                  <td style={S.td}>{r.ofOwner}</td>
                  <td style={S.td}>{r.account}</td>
                  <td style={S.td}>
                    <div>{r.func}</div>
                    {urgent && <div style={{marginTop:3}}><span style={{fontSize:10,fontWeight:700,padding:"1px 6px",borderRadius:20,background:"#dc2626",color:"#fff",whiteSpace:"nowrap",display:"inline-block"}}>🚨 URGENT</span></div>}
                  </td>
                  <td style={{...S.td,textAlign:"right",fontWeight:600,color:urgent?"#dc2626":r.aging>10?"#d97706":"#29355D"}}>{fmt1(r.aging)}</td>
                  <td style={S.td}>{r.fiNum}</td>
                  <td style={S.td}>{r.ofNum}</td>
                </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

